INSERT INTO knowledge_entries (slug, status, entry, published_at) VALUES
  ('biro-oxygen-cascade', 'published', $ke${"id": "biro-oxygen-cascade","slug": "biro-oxygen-cascade","source_pdf": "Oxygen_cascade_atmosphere_to_mitochindria.pdf","shape": "reference","document_type": "book chapter","meta_analysis": false,"key_findings": ["Oxygen falls in pressure at every step from air (~159 mmHg) to the alveoli (~100) to the tissues — that staircase is the oxygen cascade.","Nearly all oxygen travels on haemoglobin: ~20 mL per 100 mL of blood, vs ~0.3 dissolved.","Rest to maximal exercise: cardiac output rises ~5× (4.5 → 22.5 L/min) and whole-body oxygen use ~10×.","Unloading gets easier exactly where it's needed — heat, acid and CO2 shift the curve toward release.","The heart already extracts ~60% of the oxygen in its own blood at rest — its only reserve is more flow."],"header": {"title_plain": "How oxygen gets from the air to your mitochondria, and why a tenfold range in demand needs a five-fold range in cardiac output","citation": {"title": "From the Atmosphere to the Mitochondrion: The Oxygen Cascade","authors": "Biro GP","year": "not printed in source","journal": "not printed in source","volume_issue_pages": "not printed in source","doi": "not printed in source"},"topics": ["oxygen-transport","haemoglobin","cardiac-output","vo2","breathing","circulation","heart","physiology-basics"],"evidence_type": "Educational chapter, \"From the atmosphere to the mitochondrion: the oxygen cascade\" (book chapter, University of Ottawa (emeritus)) — a textbook summary of established physiology, not a study. Publication details not printed in the file — year, book title and editors to be added.","confidence": {"level": "reference","why": "Settled science; no claims to test."},"practical_relevance": {"level": "medium","why": "Not actionable by itself, but the foundation that makes VO2max, cardiac output, lactate and \"aerobic capacity\" entries make sense. Good glossary source."},"author_stance": "none apparent","funding_and_conflicts": "not stated"},"layer1": {"reference": {"what_it_explains": "Oxygen reaches muscle in four steps: breathing moves air into the lungs; oxygen diffuses into blood and binds haemoglobin; the heart pumps blood to the tissues; oxygen diffuses from capillaries into cells and mitochondria. Haemoglobin is the hinge — it carries ~60× more oxygen than blood could dissolve — and its binding curve is shaped so that it loads easily in the lungs and unloads easily in hot, acidic, CO2-rich working muscle. Total oxygen demand varies about tenfold from rest to maximal exercise; the system meets it by raising cardiac output ~5× and oxygen extraction ~2×. Oxygen delivery = cardiac output × arterial oxygen content. Oxygen content is roughly fixed by haemoglobin; cardiac output is the variable the body adjusts minute to minute.","key_numbers": [{"quantity": "Oxygen in air / arriving at the lung / in alveoli","value": "~159 / ~150 / ~100 mmHg","note": ""},{"quantity": "Oxygen carried per gram of haemoglobin","value": "1.34–1.36 mL","note": ""},{"quantity": "Arterial oxygen content at 15 g/dL haemoglobin","value": "~20 mL per 100 mL blood","note": "dissolved alone would be ~0.3"},{"quantity": "Venous blood at rest","value": "~70–75% saturated, ~40 mmHg","note": ""},{"quantity": "p50 (oxygen pressure at half-saturation)","value": "~27 mmHg","note": "shifts right (easier unloading) with heat, acid, CO2 and 2,3-DPG; 2,3-DPG can move it between 15 and 34 mmHg"},{"quantity": "Capillary transit time in the lung","value": "~0.7 s","note": ""},{"quantity": "Cardiac output, rest → max","value": "~4.5 → ~22.5 L/min (5×)","note": "heart rate ~3×, stroke volume ~2×"},{"quantity": "Whole-body oxygen use, rest → max","value": "~10×","note": ""},{"quantity": "Heart's own blood supply","value": "~5% of cardiac output, ~10% of body energy use","note": "extracts ~60% of oxygen at rest (venous saturation ~40%), so it can only meet extra demand by raising its own blood flow"},{"quantity": "Coronary perfusion","value": "mostly during diastole","note": "higher heart rates shorten the window"},{"quantity": "Work of breathing at maximal exercise","value": "becomes limiting","note": "the extra oxygen taken in is consumed by the breathing muscles"}],"scope_limits": "Nothing about training adaptations, nutrition, or performance; it's a clinical physiology chapter with examples drawn from anaemia, transfusion and heart failure. Mitochondrial oxygen levels in living tissue are, as it notes, still uncertain."}},"layer2": {"what_it_means": "Three things fall out. First, VO2max is bounded by delivery — mostly cardiac output and haemoglobin — which is why endurance adaptations are about stroke volume, blood volume and capillaries rather than lungs. Second, the right-shift of the haemoglobin curve in hot, acidic muscle is the body helping hard-working tissue; \"acidic\" is not simply bad. Third, the heart runs near its extraction ceiling at rest, so it depends on blood flow; that is why cardiac disease limits exercise first and why uncontrolled hypertension (higher afterload) matters for anyone training hard.","what_it_doesnt_mean": "Nothing about training adaptations, nutrition, or performance; it's a clinical physiology chapter with examples drawn from anaemia, transfusion and heart failure. Mitochondrial oxygen levels in living tissue are, as it notes, still uncertain.","questions_raised": []},"translation": [],"glossary_candidates": [{"term": "Haemoglobin","definition": "The protein in red blood cells that carries almost all the oxygen in blood.","confidence_term_is_new": "likely"},{"term": "Oxygen dissociation curve","definition": "The S-shaped relationship between oxygen pressure and how much haemoglobin is carrying; its shape lets blood load in the lungs and unload in muscle.","confidence_term_is_new": "likely"},{"term": "Cardiac output","definition": "Litres of blood the heart pumps per minute = heart rate × stroke volume.","confidence_term_is_new": "likely"},{"term": "Stroke volume","definition": "Blood ejected per heartbeat; the main thing endurance training enlarges.","confidence_term_is_new": "likely"},{"term": "Oxygen extraction","definition": "The fraction of delivered oxygen that tissues actually take; ~25% at rest for the body, ~60% for the heart.","confidence_term_is_new": "likely"},{"term": "Diffusion","definition": "Passive movement of a gas from high to low pressure — how oxygen crosses from air to blood and blood to cell.","confidence_term_is_new": "likely"},{"term": "Hypoxia","definition": "Oxygen supply inadequate for demand, at the tissue or cell level.","confidence_term_is_new": "likely"},{"term": "2,3-DPG","definition": "A compound in red cells that makes haemoglobin release oxygen more readily; rises in anaemia and at altitude.","confidence_term_is_new": "likely"}],"charts": [{"template": "values_by_condition","title": "The oxygen cascade: oxygen pressure at each step","series": [{"label": "Oxygen pressure","values": [{"condition": "Air","value": 159},{"condition": "Arriving at the lung","value": 150},{"condition": "Alveoli","value": 100},{"condition": "Arterial","value": 95},{"condition": "Venous","value": 40}]}],"units": "mmHg","approximate": true,"note": "Arterial value is ~95. Mitochondria ~30–40? mmHg is omitted from the bars because the chapter says mitochondrial oxygen levels in living tissue are still uncertain."},{"template": "before_after_bars","title": "Cardiac output, rest vs maximal exercise","series": [{"label": "Cardiac output","before": 4.5,"after": 22.5}],"units": "L/min","approximate": true,"note": "rest → maximal exercise, not a training change. before = rest, after = max. Heart rate ×3; stroke volume ×2; O2 use ×10."}],"verification_notes": ["Four steps: Introduction and \"Components\" section","0.03 mL/dL/mmHg, 1.34/1.36 mL/g, 20 mL/dL, 0.44 mL/dL dissolved: \"Physiological importance of the ODC\"","p50 27, right-shift factors, 2,3-DPG 15–34: same section","Tenfold VO2 range: Introduction and \"Pulmonary ventilation\"","159/150/100 mmHg: \"First step\"","0.7 s transit: \"Second step\"","4,500 → 22,500 mL/min, HR 3×, SV 2×: \"Third step\"","Heart 5% CO, 10% energy, ~40% venous sat, 11–12 mL/dL a-v difference, diastolic perfusion: \"Cardiac energetics\"","Work of breathing limiting: \"Pulmonary ventilation\"","Mitochondrial pO2 uncertainty: \"Fourth step\".","Citation incomplete in source file."]}$ke$::jsonb, now());
INSERT INTO knowledge_entries (slug, status, entry, published_at) VALUES
  ('brooks-mercier-1994', 'published', $ke${"id": "brooks-mercier-1994","slug": "brooks-mercier-1994","source_pdf": "Crossover_concept.pdf","shape": "review","document_type": "journal article","meta_analysis": false,"key_findings": ["Harder means more carbohydrate: in trained men, total fat oxidation was no higher at 85% VO2max than at 25%, despite a threefold rise in energy burned.","Training pushes the other way at easy-to-moderate intensities — lower R, spared glycogen, lower adrenaline at a given workload.","The crossover point is the power output where carbohydrate overtakes fat; training moves it to a higher absolute power.","At hard intensities, carbohydrate dominates regardless of training state.","Most lactate entering the blood (70–80%) is burned as fuel, not wasted."],"header": {"title_plain": "As exercise gets harder, carbohydrate takes over from fat as the main fuel, and endurance training moves that switch to higher workloads without stopping it.","citation": {"title": "Balance of carbohydrate and lipid utilization during exercise: the \"crossover\" concept","authors": "Brooks GA, Mercier J","year": "1994","journal": "Journal of Applied Physiology","volume_issue_pages": "76(6): 2253-2261","doi": "10.1152/jappl.1994.76.6.2253"},"topics": ["crossover-concept","substrate-utilization","fat-oxidation","carbohydrate-metabolism","fat-burning-zone","exercise-intensity","endurance-training","glycogen","catecholamines","lactate-threshold","zone-2","fuel-use"],"evidence_type": "Brief narrative review proposing a conceptual model; no new data collected; no systematic search (the authors say they cite 'the significant work that we believe supports our concept'); the model's central figure (Fig 1) is a schematic, not plotted data.","confidence": {"level": "conceptual","why": "The authors call the crossover concept 'a theoretical construct' and say the experiments needed to substantiate it have not been done; its strength rests on the cited studies, several of which are small, in animals, or tested at only one intensity."},"practical_relevance": {"level": "high","why": "It is the standard framework behind 'fat-burning zone' and zone-based fuel advice, and it changes how a coach explains intensity, fuel use and why race-pace work runs on carbohydrate."},"author_stance": "The paper does not name the lactate shuttle, but it reveals a lactate-centred view from Brooks's own lab: 16 of the 62 references include Brooks as an author (refs 3-8, 14, 15, 18, 23, 27, 39, 43, 46, 52, 57), it cites unpublished data from his lab, it stresses lactate oxidation and lactate as a gluconeogenic fuel, and the authors state that they cite only the work they believe supports their concept.","funding_and_conflicts": "Supported by National Institutes of Health Grants DK-19577 and AR/DK-42906. Conflicts of interest not stated."},"layer1": {"review": {"claim": "The balance of carbohydrate and fat used during sustained exercise depends on two opposing influences. Rising exercise intensity increases carbohydrate use, through faster muscle glycogen breakdown, recruitment of fast glycolytic fibres and greater sympathetic nervous system (adrenaline) activity. Endurance training pushes the other way, through more mitochondria and a smaller sympathetic response to a given workload, which favours fat oxidation at mild-to-moderate intensities. The crossover point is the power output above which carbohydrate supplies more energy than fat, with carbohydrate's share rising and fat's falling as intensity increases further. Training moves the crossover to a higher absolute power output, but at hard intensities carbohydrate dominates regardless of training state, so studies showing more fat use after training and studies showing carbohydrate dependence in athletes are, the authors argue, consistent.","definitions_used": [{"term": "Crossover point","definition": "The power output at which energy derived from oxidation of carbohydrate-based fuels predominates over that derived from lipids, with further increases in power producing a relative increase in carbohydrate energy and a relative decrease in fat energy. No numeric %VO2max is given for the crossover point in the text."},{"term": "Mild intensity","definition": "A lesser metabolic response than moderate exercise, e.g. ≤45% VO2max."},{"term": "Moderate intensity","definition": "A leg power output that elicits 50-55% of whole-body VO2max."},{"term": "Hard intensity","definition": "A greater metabolic response than moderate exercise, e.g. ≥65% VO2max in the main text; the abstract gives '~75% maximal O2 uptake' as its example of hard-intensity exercise."},{"term": "Training","definition": "Regularly performed endurance exercise at an intensity sufficient to induce both central circulatory and peripheral muscle mitochondrial adaptations."},{"term": "Carbohydrates (CHO)","definition": "Endogenous sources: muscle and liver glycogen; blood glucose; and blood, muscle and liver lactate."},{"term": "Lipids","definition": "Adipose and intramuscular triglycerides, plus blood-borne free fatty acids (FFAs) and triglycerides."},{"term": "Utilization","definition": "Disposal (disappearance) from blood or another storage compartment; for CHO this can be anaerobic glycolysis, gluconeogenesis or oxidation; for lipids, oxidation or re-esterification. The authors use 'lipid oxidation' but 'CHO utilization' because carbohydrate can also yield energy anaerobically."},{"term": "Anaerobic glycolysis","definition": "Glycogenolysis or glycolysis leading to net lactate accumulation in blood, muscle or another compartment."},{"term": "Absolute vs relative intensity","definition": "Not defined as a term, but central to the argument: testing at the same absolute power output before and after training means testing at a lower relative intensity after training, which the authors say 'missed the crossover to CHO dependency'."}],"evidence_cited": [{"finding": "Four sets of findings support more fat oxidation after training during submaximal exercise: more mitochondria, lower respiratory exchange ratio (R), muscle glycogen sparing, and lower blood catecholamines and lactate at a given power output.","source": "Refs 1, 3, 11, 12, 15, 17, 21, 22, 28, 29, 36, 39, 40, 59 (as grouped by the authors)","numbers": "No values given","note": "Supporting evidence for the training arm of the model."},{"finding": "A lower R at a given submaximal power output after training is 'a highly reproducible observation' and, under steady-state conditions, 'probably represent[s] the strongest data available' for enhanced fat oxidation after training.","source": "Gollnick 1985 (ref 21)","numbers": "No values given","note": "Authors flag the assumption that R equals the tissue respiratory quotient."},{"finding": "Net muscle glycogen breakdown is less after training; the blunting is most prominent at the rest-to-exercise transition.","source": "Rat (ref 1) and human (refs 21, 36) biopsy studies","numbers": "No values given","note": "Authors say studies on the mechanism of glycogen sparing are lacking."},{"finding": "Against the usual explanation: increased blood glucose uptake, not increased fat use, explained most of the muscle glycogen sparing in trained rats during moderate-to-hard exercise.","source": "Donovan & Sumida 1990 (ref 19)","numbers": "No values given","note": "Animal data. Cuts against the idea that glycogen sparing means more fat burning."},{"finding": "In fit subjects cycling hard, palmitate (blood fatty acid) turnover fell compared with rest.","source": "Jones et al. 1980 (ref 35)","numbers": "Cycling at 70% VO2max","note": "Consistent with dog data (ref 32) showing reduced lipolysis and FFA turnover when lactic acidosis occurs."},{"finding": "In marathon running, palmitate turnover rose only slightly while glucose appearance rose; across these two reports, oxygen uptake, CO2 output and total CHO oxidation rose far more, so the relative contribution of blood FFAs fell.","source": "Hall et al. 1983 (ref 25); Jones et al. 1980 (ref 35)","numbers": "Glucose appearance rate increased twofold over resting values (Hall); VO2, CO2 output and total CHO oxidation increased ~15-fold compared with rest (both reports)","note": "Authors: 'a small absolute increase but relative decline in lipid oxidation at relatively high power outputs, even in highly trained individuals, is predicted by the crossover concept.' Authors also note these two reports are 'generally ignored', and that the literature on FFA turnover in trained vs untrained humans is thin, early data came from dogs, and no rat reports show increased FFA turnover with training."},{"finding": "Glucose turnover declines after training during mild-to-moderate exercise, but this and similar studies tested the same absolute power output before and after training.","source": "Coggan et al. 1990 (ref 11); see also refs 11-13","numbers": "Exercise at 50% of pretraining VO2max = 40-45% of posttraining VO2max; blood glucose concentration and turnover decreased vs pretraining","note": "Authors argue these protocols 'missed the crossover to CHO dependency by not testing subjects at higher exercise intensities'."},{"finding": "Training also raises the capacity to use glucose: muscle GLUT-4 and hexokinase increase, and liver gluconeogenic capacity improves.","source": "Refs 2, 31, 53 (ref 53 is rat liver in situ)","numbers": "No values given","note": "Authors: these adaptations 'favor increased blood glucose utilization and glycogen sparing, not increased lipid oxidation'. Cuts against a fat-only reading of training adaptations."},{"finding": "In trained vs untrained men exercising hard, arterial glucose concentration and appearance rate are higher in the trained.","source": "Kjaer et al. 1986 (ref 40)","numbers": "Exercise eliciting ≥60% VO2max","note": "Same reference: catecholamine rise at moderate-to-hard intensity is greater in highly trained than less fit individuals."},{"finding": "After training, at a given submaximal workload insulin falls less and glucagon and catecholamines rise less; during mild-to-moderate exercise circulating adrenaline rises little if at all above rest.","source": "Refs 12, 17, 24, 42","numbers": "Authors predict adrenaline may not rise above rest at an intensity eliciting 40-50% of posttraining VO2max","note": "The 40-50% figure is the authors' prediction, not a cited measurement."},{"finding": "A few training sessions changed substrate use (lower lactate and R) before mitochondrial or circulatory adaptations occurred.","source": "Green et al. 1992 (ref 22)","numbers": "No values given","note": "Catecholamines were not reported; authors read this as consistent with reduced sympathetic drive shifting the crossover."},{"finding": "Conflicting training effects on fat mobilisation: adipocytes from trained people show enhanced lipolysis to adrenaline, but in trained rats insulin's suppression of plasma FFA is increased; circulating FFA is lower after training at a given mild-to-moderate workload.","source": "Refs 16, 41, 47, 48, 11","numbers": "No values given","note": "Authors: resolution of these conflicting effects 'remains to be achieved'."},{"finding": "Subjects with low lactate thresholds had higher blood glucose turnover than those with high thresholds.","source": "Coggan et al. 1992 (ref 12)","numbers": "No values given","note": "Sympathetic responses not reported; offered as a possible link between lactate threshold and crossover point."},{"finding": "In trained subjects, muscle citrate was elevated but glucose 6-phosphate unchanged versus pretraining.","source": "Coggan et al. 1993 (ref 13)","numbers": "Power output eliciting 50% of pretraining VO2max","note": "Authors state the results 'are also inconsistent with the suggested training effect of raising glucose-fatty acid cycle activity in humans'. Cuts against one proposed mechanism for more fat use after training."},{"finding": "Most lactate entering the blood is oxidised, so VO2 represents most of the energy used below the lactate threshold.","source": "Refs 18, 43","numbers": "70-80% of lactate appearing in blood disposed of through oxidation","note": "Both references are from Brooks's lab."},{"finding": "Training increases leucine oxidation during exercise, but amino acids contribute little to total fuel.","source": "Henderson et al. 1985 (ref 27)","numbers": "~1% of overall substrate oxidation","note": "Rat study per its reference title; relative contribution falls as intensity rises."},{"finding": "High-fat diets with adequate calories can increase fat oxidation at rest and during exercise and maintain blood glucose during prolonged submaximal exercise.","source": "Phinney et al. 1983 (ref 49)","numbers": "Adaptation requires 'several weeks, if not months'","note": "Authors: unclear that this would permit sustained high-power exercise as used in competition."},{"finding": "Trained women compared with men showed lower R, lower circulating adrenaline and less muscle glycogen depletion.","source": "Tarnopolsky et al. 1990 (ref 55)","numbers": "Running 90-101 min at 65% VO2max","note": "Authors: no published attempts to measure substrate flux rates in men and women; 'such data need to be supplied'."},{"finding": "Raising blood fatty acids several-fold with Intralipid and heparin did not significantly improve endurance.","source": "Van Baak et al. 1993 (ref 57a)","numbers": "Male subjects at 70% VO2max; non-esterified fatty acids and glycerol 'several times over' saline control; endurance not significantly improved","note": "Authors: muscles were carbohydrate-dependent at that intensity, so extra fat supply did not help."},{"finding": "In highly trained men, plasma FFA appearance fell and glucose appearance rose in direct proportion to exercise intensity; total fat oxidation was no different at 85% than at 25% VO2max despite a threefold increase in energy expenditure.","source": "Romijn et al. 1993 (ref 51a)","numbers": "5 highly trained men; 25, 65 and 85% VO2max; threefold increase in energy expenditure; total fat oxidation (indirect calorimetry) no different at 85% vs 25% VO2max","note": "No fuel-split percentages or oxidation rates at each intensity are printed in this review. Key point for the fat-burning-zone belief: the higher fat share at 25% did not mean more total fat burned than at 85%."},{"finding": "After training, at the same absolute workload, R fell (interpreted as more total fat oxidation) but plasma FFA turnover and oxidation also fell; investigators attributed the extra fat use to intramuscular lipid.","source": "Martin et al. 1993 (ref 42a)","numbers": "10 men and 3 women; same power output elicited 58% VO2max before and 46% VO2max after training (from that paper's Tables 1 and 2)","note": "Partly cuts against a simple 'training burns more blood fat' reading. No sympathetic or lipolysis data available. Authors: shifting exercise to a relatively lesser level 'increases total lipid oxidation if not FFA oxidation'."}],"recommendations_made": [],"untested_or_contested": "The authors call the concept 'a theoretical construct' and say they 'have likely oversimplified the presentation of a complex problem'. Experiments measuring glucose, glycerol and FFA kinetics, glycogen depletion and glucoregulatory hormones across graded intensities after short- and long-term training 'are required to substantiate the crossover concept'. Experiments establishing the role of sympathetic stimulation in shifting fuel from fat to carbohydrate 'have not yet been done'. It remains to be determined which, if any, blood lactate concentration correlates with the crossover point, and anaerobic energy in maximal exercise cannot currently be quantified. Mechanisms of training-induced glycogen sparing are little studied, and conflicting training effects on fat mobilisation are unresolved. No published study had compared substrate flux in men and women. Data on fat turnover in trained versus untrained humans are scarce, and early work used dogs, which are hard to extrapolate to humans. Effects of nutrition, environment, fibre type, sex and hormone sensitivity are not surveyed. Whether high-fat-diet adaptation would support sustained high-power exercise is unclear. The Fig 1 legend states that on a relative basis training 'probably' has minimal effects on the curves."}},"layer2": {"what_it_means": "Fuel use is a sliding balance, not a switch. At rest and easy intensities fat supplies most of the energy; as intensity climbs, carbohydrate takes a growing share, and above the crossover point it supplies most of the energy. Endurance training moves that point to a higher absolute workload, so a trained person uses a bigger fat share at the same pace, partly because that pace is now a smaller fraction of their maximum. In the Martin study the same workload went from 58% to 46% VO2max after training. Training does not abolish the switch: during hard work, which the authors put at ≥65% VO2max and which covers most athletic training and racing above 70-75% of maximum, carbohydrate dominates in trained people too. Raising blood fat several-fold at 70% VO2max did not improve endurance. For a coach, the practical message is that fuelling and glycogen matter for hard sessions and races, that easy aerobic work is where fat supplies the bigger share, and that 'trained people burn more fat' applies at the same absolute pace, not at the same relative effort.","what_it_doesnt_mean": "It does not support the 'fat-burning zone' belief that low intensity burns more fat. The crossover describes fat's share of energy, not the total amount of fat burned. In the one study here that measured total fat oxidation across intensities, five highly trained men burned no more fat at 25% than at 85% VO2max, while energy use at 85% was three times higher. Nothing here measures fat loss over weeks, energy balance or after-exercise fuel use, so it says nothing about which intensity loses more body fat. This is one group's model, built partly on Brooks's own lab work and on studies chosen because they support it. Its figure is a drawing, not data, and it gives no specific %VO2max for the crossover point. Much of the evidence compares people or tests one intensity, some comes from rats and dogs, and the authors say the confirming experiments had not been done. Women, untrained or overweight people, and older adults were barely studied.","questions_raised": []},"translation": ["Easy work, around 45% of max or below, runs mainly on fat in trained people; hard work, 65% of max and up, runs mainly on carbs, trained or not.","Getting fitter makes a given pace easier: in one study the same workload went from 58% to 46% of max after training, so more of it came from fat.","A bigger fat share isn't more fat burned: 5 trained men burned no more fat at 25% of max than at 85%, while burning three times the energy at 85%.","Most hard training and racing sits above 70-75% of max, where carbs are the main fuel."],"glossary_candidates": [{"term": "Crossover point","definition": "The exercise intensity above which carbohydrate supplies more of the body's energy than fat does.","confidence_term_is_new": "likely"},{"term": "Substrate","definition": "A fuel the body breaks down for energy, mainly carbohydrate, fat and, to a small extent, protein.","confidence_term_is_new": "likely"},{"term": "Glycogen","definition": "The stored form of carbohydrate, kept in muscles and the liver.","confidence_term_is_new": "unsure"},{"term": "Glycogen sparing","definition": "Using less stored muscle carbohydrate for the same exercise, usually because another fuel such as fat or blood sugar covers more of the demand.","confidence_term_is_new": "likely"},{"term": "Free fatty acids (FFA)","definition": "Fat molecules released from fat stores into the blood, where muscles can take them up and burn them.","confidence_term_is_new": "likely"},{"term": "Fat oxidation","definition": "Burning fat for energy at a given moment; not the same as losing body fat over time.","confidence_term_is_new": "unsure"},{"term": "Respiratory exchange ratio (R or RER)","definition": "The ratio of carbon dioxide breathed out to oxygen taken in; lower values mean more fat is being burned, higher values mean more carbohydrate.","confidence_term_is_new": "likely"},{"term": "Sympathetic nervous system (SNS)","definition": "The 'fight or flight' system that ramps up during hard exercise and releases adrenaline and noradrenaline.","confidence_term_is_new": "likely"},{"term": "Adrenaline (epinephrine) / catecholamines","definition": "Stress hormones that rise with hard exercise; adrenaline speeds the breakdown of muscle glycogen. Catecholamines is the group name for adrenaline and noradrenaline.","confidence_term_is_new": "likely"},{"term": "Lactate threshold","definition": "The exercise intensity at which lactate starts building up in the blood faster than the body can clear it.","confidence_term_is_new": "unsure"},{"term": "Isotope tracer","definition": "A labelled version of a molecule, such as a fatty acid or glucose, infused into the blood so researchers can track how fast that fuel is released and used.","confidence_term_is_new": "likely"},{"term": "Absolute vs relative intensity","definition": "Absolute intensity is the actual workload (watts or pace); relative intensity is that workload as a percentage of a person's own maximum. After training, the same absolute workload is a lower relative intensity.","confidence_term_is_new": "likely"},{"term": "VO2max","definition": "The most oxygen a person can use per minute during all-out exercise; intensities are often given as a percentage of it.","confidence_term_is_new": "unsure"},{"term": "Turnover / rate of appearance","definition": "How fast a fuel such as glucose or fatty acids enters (and leaves) the blood, as opposed to its concentration at one moment.","confidence_term_is_new": "likely"},{"term": "Gluconeogenesis","definition": "The liver making new glucose from other molecules, including lactate.","confidence_term_is_new": "likely"}],"charts": [{"template": "concept_curve","title": "The crossover: fat's and carbohydrate's share of energy as intensity rises","series": [{"label": "Fat (% of energy)","points": [{"x": 0,"y": 60},{"x": 20,"y": 54},{"x": 40,"y": 45},{"x": 60,"y": 35},{"x": 80,"y": 22},{"x": 100,"y": 0}]},{"label": "Carbohydrate (% of energy)","points": [{"x": 0,"y": 40},{"x": 20,"y": 46},{"x": 40,"y": 53},{"x": 60,"y": 62},{"x": 80,"y": 80},{"x": 100,"y": 100}]}],"units": "x = aerobic power, % of maximum (x = 0 stands for 'Rest'); y = % of energy from each fuel","approximate": true,"note": "schematic — not measured data. Values approx., read from Fig 1, which is a drawing. In the original, fat is plotted on a 0-60% left axis and carbohydrate on a 40-100% right axis, so the point where the two lines cross on the page (about 70% aerobic power) is not where carbohydrate passes 50%; on the printed scales that happens at roughly 30-40% aerobic power. The figure has arrows showing training shifts curves rightward and sympathetic (SNS) stimulation shifts them leftward. The legend says that on a relative basis training 'probably has minimal effects' on the curves."},{"template": "values_by_condition","title": "Same workload, lower relative intensity after training (Martin et al.)","series": [{"label": "Relative intensity of the same absolute power output","values": [{"condition": "Before training","value": 58},{"condition": "After training","value": 46}]}],"units": "% VO2max","approximate": false,"note": "Second-hand: the review authors' reporting of Martin et al. 1993 (10 men, 3 women), taken from that paper's Tables 1 and 2. Shows why studies at a fixed absolute workload find more fat use after training. No Romijn fuel-split chart: the review prints no fat/carbohydrate percentages or oxidation rates at 25, 65 or 85% VO2max, only that total fat oxidation did not differ between 85% and 25%."}],"verification_notes": ["All numbers are the review authors' reporting of cited studies; not verified against originals.","Page numbers below are journal pages; PDF p.1 is a ResearchGate cover sheet, so journal p.2253 = PDF p.2 through p.2261 = PDF p.10.","Citation, authors, journal, 76(6): 2253-2261, 1994: p.2253 (abstract header). DOI 10.1152/jappl.1994.76.6.2253: printed only on the ResearchGate cover sheet (PDF p.1), not on the article pages.","Document type: labelled 'brief review' in the banner, p.2253; 'theoretical means' in abstract, p.2253.","Crossover point definition: p.2253 (abstract and main text) and Fig 1 legend, p.2254.","Abstract figures, '≤45% maximal O2 uptake' lipid main substrate after training, '~75% maximal O2 uptake' hard exercise, athletes '>70-75% of maximum aerobic power': p.2253.","Intensity bands, moderate 50-55% VO2max, mild ≤45%, hard ≥65%; definitions of training, CHO, lipids, utilization, anaerobic glycolysis: p.2254.","No numeric %VO2max for the crossover point appears anywhere in the text; the caller's '50-65% VO2max' range is not printed in this document.","Fig 1 schematic: p.2254; axes Fat 0-60% (left), CHO 40-100% (right), aerobic power Rest-100%; concept_curve values approx., from Fig 1.","Leucine oxidation ~1% of substrate oxidation: p.2254.","Lactate 70-80% disposed through oxidation; anaerobic energy minimal below lactate threshold: p.2255.","Four sets of findings for training-increased lipid oxidation; mitochondrial reticulum; R reproducible: p.2255.","R 'strongest data'; glycogen sparing biopsies; Donovan & Sumida challenge; unpublished Azevedo/Lehman/Brooks data (printed as 'Brouns'): p.2256.","Jones et al. 70% VO2max palmitate turnover decrease; Hall et al. twofold glucose appearance; ~15-fold increase; dogs and rats paucity of data: p.2256.","Absolute vs relative paradigm, Coggan refs 11-13, 'missed the crossover'; GLUT-4, hexokinase, gluconeogenesis: p.2256.","Hormonal responses after training; catecholamines greater in highly trained (ref 40); Green et al. few bouts; adipocyte vs insulin FFA conflict; prediction that adrenaline may not rise at 40-50% posttraining VO2max: p.2257.","Kjaer ≥60% VO2max glucose; Coggan 50% pretraining = 40-45% posttraining VO2max; SNS experiments 'not yet been done'; Coggan low vs high lactate threshold; citrate/G6P 'inconsistent with... glucose-fatty acid cycle'; lactate-crossover correlation undetermined; glycogen depletion shifts curves: p.2258.","High-fat diet adaptation 'several weeks, if not months': pp.2258-2259.","Tarnopolsky 90-101 min at 65% VO2max; no flux data in men vs women: p.2259.","Van Baak 70% VO2max, Intralipid + heparin, FFA several times control, endurance not significantly improved: p.2259.","Romijn 5 highly trained men, 25/65/85% VO2max, FFA appearance down and glucose appearance up in proportion to intensity, threefold energy expenditure, total fat oxidation no different 85% vs 25%: p.2259. No fuel-split numbers printed.","Martin 10 men and 3 women, 58% VO2max before / 46% after training, R down, plasma FFA turnover and oxidation down, intramuscular lipid conclusion: p.2259.","Summary; 'theoretical construct'; experiments 'required to substantiate the crossover concept': pp.2259-2260.","Authors' limitations, 'likely oversimplified', no extensive survey, cite work 'we believe supports our concept': p.2254.","Funding NIH DK-19577 and AR/DK-42906: p.2260. No conflict statement printed.","Author stance count, 16 of 62 references with Brooks as author (refs 3-8, 14, 15, 18, 23, 27, 39, 43, 46, 52, 57): reference list pp.2260-2261. Lactate shuttle is not named in the paper.","recommendations_made left empty: the paper makes no explicit practical recommendations; the statement that athletes train and compete above 70-75% and depend on CHO (p.2253) is descriptive."]}$ke$::jsonb, now());
INSERT INTO knowledge_entries (slug, status, entry, published_at) VALUES
  ('conley-2001', 'published', $ke${"id": "conley-2001","slug": "conley-2001","source_pdf": "Limits_to_sustainable_muscle_performance_-_interaction_between_.pdf","shape": "review","document_type": "journal article","meta_analysis": false,"key_findings": ["Sustainable power is roughly ⅓ of your best few-second power; trained cyclists hold ~80% of VO2max-test power for 30 minutes.","Even in steady state, glycolysis supplies 10–12% of ATP (up to ~20%) — and the acid it makes suppresses ADP, the signal that drives the mitochondria.","Mitochondria in sustained exercise run well below capacity: peak steady-state ADP is 0.06–0.11 mmol/L vs ~0.3 needed for full drive — oxygen isn't the limiter.","Full mitochondrial drive is reachable (quads at VO2max: ADP 0.25, pH 6.5) but sustainable for under 5 minutes.","Raising the ceiling means making less acid per watt and clearing it faster — the snake muscle that sustains >80% of capacity for hours has half-diameter fibres (33 vs 67 µm) and ~35% more blood flow."],"header": {"title_plain": "Why you can't hold your top aerobic pace: acid from glycolysis blunts the signal that drives the mitochondria","citation": {"title": "Limits to sustainable muscle performance: interaction between glycolysis and oxidative phosphorylation","authors": "Conley KE, Kemper WF, Crowther GJ","year": "2001","journal": "J Exp Biol","volume_issue_pages": "204: 3189–3194","doi": "not printed in source"},"topics": ["sustainable-power","steady-state","glycolysis","mitochondria","ph","lactate","threshold","muscle-energetics"],"evidence_type": "Review/hypothesis built on the authors' 31P-MRS studies of human muscle and rattlesnake tail-shaker muscle, plus cited literature. NIH and NSF funded.","confidence": {"level": "conceptual","why": "A coherent mechanistic argument, partly validated in an animal model."},"practical_relevance": {"level": "low","why": "Mechanism paper with one actionable framing (sustainable pace is set by acid build-up, which endurance adaptations reduce); hand entry said low–medium, low chosen."},"author_stance": "none apparent","funding_and_conflicts": "NIH and NSF funded."},"layer1": {"review": {"claim": "The power you can sustain for more than a few minutes is set inside the muscle, by whether ATP supply can match demand. Even in fully aerobic steady-state exercise, glycolysis supplies a sizeable share of ATP and so produces acid (H+). That acid lowers the concentration of ADP, which is the signal that tells mitochondria how hard to work. So mitochondria in sustained exercise run well below their capacity — not because oxygen is short, but because the activating signal is suppressed. Three phases follow: fatiguing high power (seconds), a transitional zone (seconds to minutes, PCr and pH drifting down), and the sustainable zone.","definitions_used": [],"evidence_cited": [{"finding": "Sustainable power is a fraction of max","source": "Wilkie; cycling data","numbers": "~⅓ of maximal power sustainable for prolonged periods; cyclists hold ~80% of their VO2max-test power for 30 min","note": ""},{"finding": "Glycolysis contributes to steady-state ATP in humans","source": "Authors' MRS, 3 human muscles","numbers": "10–12% of ATP from glycolysis producing lactate; up to ~20% including the glycolytic step on the way to oxidation; vs 8% expected if all pyruvate were oxidised","note": ""},{"finding": "Extreme case validates the method","source": "Rattlesnake tail-shaker, 50 Hz for hours","numbers": "Glycolysis >⅓ (~40%) of sustained ATP; MRS estimate matched direct lactate measurement","note": "Animal data."},{"finding": "Mitochondria are not fully switched on in steady state","source": "Literature + isolated mitochondria curve","numbers": "Highest steady-state ADP in muscle 0.06–0.11 mmol/L; ~0.3 mmol/L needed to elicit full oxidative capacity. Steady-state PCr falls only to ~half resting","note": ""},{"finding": "Full activation is possible, briefly","source": "Quadriceps at VO2max (Richardson 1995)","numbers": "PCr down to 3 mmol/L, pH 6.5, ADP 0.25 mmol/L — near maximal mitochondrial drive, sustainable <5 min","note": ""},{"finding": "Keeping pH high is the other route","source": "Tail-shaker muscle","numbers": "pH 7.2 (vs 6.5 in human quads at VO2max), PCr 10 mmol/L, ADP 0.15 → >80% of oxidative capacity, sustained. Achieved by fibres half the diameter (33 vs 67 µm) and blood flow 468 vs 350 ml/100 g/min in human athletes","note": "Animal data."},{"finding": "Oxygen isn't the limiter at steady state","source": "cited","numbers": "O2 delivery may limit near VO2max in athletes, but not at the lower rates of steady-state work; glycolysis is independent of oxygenation in stimulated human muscle","note": ""},{"finding": "PCr recovery slows at low pH","source": "rodent/human","numbers": "cited, no numbers","note": ""}],"recommendations_made": [],"untested_or_contested": "Whether pH acts on the ADP signal or directly on mitochondria. The argument is a \"contention\" supported by MRS; direct whole-body confirmation isn't available."}},"layer2": {"what_it_means": "This is the physiology behind the lactate/anaerobic threshold, told from inside the cell. Your sustainable pace isn't capped by the lungs or the heart at that intensity; it's capped by acid accumulation turning down the mitochondria's throttle. Two things raise the ceiling: fewer H+ produced per unit of work, and faster H+ removal — the snake does it with tiny fibres and enormous blood flow. In human terms that's the rationale for the adaptations endurance training produces (more capillaries, more mitochondria, better buffering and lactate clearance), and it explains why the threshold, not VO2max, tracks what you can actually hold.","what_it_doesnt_mean": "It's a mechanism paper with no training intervention and one validated animal model; the human numbers are from small MRS studies of single muscles. It doesn't tell you how to raise the threshold, only what sets it. Don't read \"glycolysis supplies 10–20% of steady-state ATP\" as \"steady-state exercise is 20% anaerobic\" in the sense coaches use — the lactate produced is largely re-oxidised. And the ⅓-of-max and 80%-for-30-min figures are illustrative, not prescriptive.","questions_raised": []},"translation": ["Sustainable power ≈ ⅓ of your best few-second power; ~80% of VO2max-test power holds for ~30 min in cyclists.","What limits it: acid build-up dampening the signal to the mitochondria, not oxygen supply.","What raises it: producing less acid per watt and clearing it faster — the adaptations endurance training targets."],"glossary_candidates": [{"term": "ADP","definition": "What's left when ATP is spent; its rise is the signal that tells mitochondria to make more ATP.","confidence_term_is_new": "likely"},{"term": "Oxidative phosphorylation","definition": "The mitochondrial process that makes ATP using oxygen.","confidence_term_is_new": "likely"},{"term": "Steady state","definition": "Exercise at an intensity where PCr, pH and oxygen uptake stop drifting — sustainable for long periods.","confidence_term_is_new": "likely"},{"term": "Intracellular pH / H+","definition": "Acidity inside the muscle fibre; falls (acid rises) with hard work and interferes with energy signalling.","confidence_term_is_new": "likely"},{"term": "Buffering","definition": "The muscle's capacity to absorb acid; improves with training.","confidence_term_is_new": "likely"},{"term": "Capillary density","definition": "How many small blood vessels surround each fibre; more means faster delivery of oxygen and removal of acid.","confidence_term_is_new": "likely"}],"charts": [{"template": "concept_curve","title": "Power–duration curve","series": [{"label": "Power","points": [{"x": 1,"y": 650},{"x": 5,"y": 280}]}],"units": "min (x); W (y)","approximate": true,"note": "schematic — not measured data. From Fig 1: ~650 W at <1 min falling to ~280 W by 5 min and flat thereafter (x = 1 stands for \"<1 min\")."},{"template": "values_by_condition","title": "ADP: steady state vs full mitochondrial drive","series": [{"label": "ADP","values": [{"condition": "Human steady state (highest)","value": "0.06–0.11"},{"condition": "Needed for full capacity","value": "~0.3"},{"condition": "Human quads at VO2max","value": "0.25"},{"condition": "Snake sustained (animal)","value": "0.15"}]}],"units": "mmol/L","approximate": false,"note": "Snake value is from rattlesnake tail-shaker muscle (animal)."},{"template": "values_by_condition","title": "Glycolytic share of steady-state ATP","series": [{"label": "Glycolytic share","values": [{"condition": "Human","value": "10–12 (up to 20)"},{"condition": "Snake (animal)","value": "~40"}]}],"units": "% of ATP","approximate": false,"note": "Snake value is from rattlesnake tail-shaker muscle (animal)."}],"verification_notes": ["All numbers are the review authors' reporting of cited studies; not verified against originals.","⅓ sustainable, 80% for 30 min: pp.3189–3190","10–12%, 8%, 20%: p.3191","Snake >⅓, MRS vs lactate: p.3191","ADP 0.06–0.11, 0.3, PCr ~half: p.3192","Richardson PCr 3, pH 6.5, ADP 0.25: p.3193","Snake pH 7.2, PCr 10, ADP 0.15, >80%, 33 vs 67 µm, 468 vs 350: p.3193","O2 not limiting: p.3191","Three phases: p.3194","Funding: p.3194","\"contention\": pp.3189, 3191"]}$ke$::jsonb, now());
INSERT INTO knowledge_entries (slug, status, entry, published_at) VALUES
  ('escalante-barakat-2020', 'published', $ke${"id": "escalante-barakat-2020","slug": "escalante-barakat-2020","source_pdf": "Fasted_Versus_Nonfasted_Aerobic_Exercise_on_Body_Composition.pdf","shape": "review","document_type": "journal article","meta_analysis": false,"key_findings": ["Fasted cardio does burn more fat during the session (27 studies, 273 participants, low intensity).","Over weeks it doesn't matter: the best-controlled trial lost 26.3→25.0% body fat fasted vs 24.8→24.1% fed in 4 weeks — no meaningful difference.","Pooled trials (5 studies, 96 people) show trivial-to-small differences in weight, body fat and lean mass.","Fasted work has costs: ~14 g of amino acids lost per hour, and eating first raises post-exercise energy burn.","Protein before cardio raised post-exercise energy expenditure — a practical middle ground the authors suggest for physique athletes."],"header": {"title_plain": "Fasted cardio burns more fat during the session — and doesn't change how much fat you lose","citation": {"title": "Fasted Versus Nonfasted Aerobic Exercise on Body Composition: Considerations for Physique Athletes","authors": "Escalante G, Barakat C","year": "2020","journal": "Strength Cond J","volume_issue_pages": "not printed in source","doi": "10.1519/SSC.0000000000000565"},"topics": ["fasted-cardio","fat-loss","body-composition","physique","nutrition","protein","fat-oxidation"],"evidence_type": "Narrative review aimed at physique athletes, drawing on two meta-analyses of acute effects, one meta-analysis of body-composition outcomes (5 studies, 96 people), and a handful of trials.","confidence": {"level": "moderate","why": "The \"no difference\" finding rests on meta-analyses; the physique-athlete caveats are the authors' speculation."},"practical_relevance": {"level": "high","why": "Directly answers one of the most common \"I saw it online\" questions."},"author_stance": "one author is a physique coach (stated); no conflicts declared","funding_and_conflicts": "No funding; no conflicts (one author is a physique coach)."},"layer1": {"review": {"claim": "Fasted aerobic exercise does raise fat oxidation during the session and has some favourable acute effects. But controlled studies find trivial-to-no difference in fat loss between fasted and fed cardio when calories are matched. Physique athletes at very low body fat haven't been studied, so small advantages can't be ruled out. Protein before cardio may be the best of both.","definitions_used": [],"evidence_cited": [{"finding": "Fasted exercise burns more fat during the session","source": "Vieira 2016 meta-analysis","numbers": "27 studies, 273 participants; low-intensity (~40–70% HRmax); blood glucose not different (p = 0.91)","note": ""},{"finding": "Fasted training raises stored muscle glycogen","source": "Van Proeyen 2011","numbers": "+22% basal muscle glycogen in fasted group; no change fed","note": ""},{"finding": "Fasted exercise uses fat stored inside muscle","source": "De Bock / van Loon","numbers": "intramuscular triglyceride ↓ ~60% fasted; no change fed","note": ""},{"finding": "More fatty acids circulate when fasted","source": "Aird 2018 meta-analysis","numbers": "46 studies; FFA higher fasted; other markers mixed and population-dependent","note": ""},{"finding": "30-day trial, fasted vs fed","source": "Trabelsi 2012 (Ramadan)","numbers": "19 active men, 3×/wk, 40–60 min at 60–80% HRmax. Weight: fasted 79.2→77.7 kg, fed 80.5→78.4 kg (both sig). Body fat: fasted 19.4→18.6% (sig), fed 19.3→18.8% (not sig).","note": "But fed group ate 3,056 vs 2,466 kcal/day (calorie confound); skinfold measurement."},{"finding": "Pooled body-composition outcomes","source": "Hackett & Hagstrom 2017 meta-analysis","numbers": "5 studies, 96 participants (60 M, 36 F), age 21–27: trivial-to-small effects on weight, % fat, lean mass","note": ""},{"finding": "Best-controlled trial","source": "Schoenfeld 2014","numbers": "20 women, 4 weeks, hypocaloric diet, 1.8 g/kg protein, 60 min walking 3×/wk supervised. Fasted: 26.3→25.0% fat, 16.5→15.4 kg fat. Fed: 24.8→24.1%, 15.7→15.0 kg.","note": "No significant difference."},{"finding": "Fasted cardio costs some protein","source": "Lemon & Mullin 1980","numbers": "nitrogen loss ≈ 14 g amino acids/h during 60 min fasted exercise","note": ""},{"finding": "Eating first raises post-exercise burn","source": "several","numbers": "greater post-exercise energy expenditure fed vs fasted","note": ""},{"finding": "Protein before cardio","source": "Gieske 2018 pilot","numbers": "11 men, crossover: 25 g whey / casein / maltodextrin / nothing, then 30 min at 55–60% HR reserve. Protein → higher post-exercise energy expenditure and fat oxidation; casein > whey during exercise; fasting did not raise fat oxidation","note": ""}],"recommendations_made": ["Protein before cardio is the authors' own practical pick: it may protect muscle, slightly raises post-exercise burn, and doesn't blunt fat use the way carbohydrate does.","Avoid fasted sessions longer than 60 minutes because of protein loss."],"untested_or_contested": "No studies in physique competitors (lean, high-protein, resistance-trained, 8–16+ week preps). Small effects below statistical significance might matter at the margin of competition. Thermogenic supplements commonly taken before fasted cardio may change the picture."}},"layer2": {"what_it_means": "Burning more fat during a workout and losing more fat overall are different things, and the evidence separates them cleanly. Fasted cardio shifts fuel use for an hour; over weeks, the body balances it out, and fat loss tracks the calorie deficit. So the honest answer to \"should I do fasted cardio?\" is: if you like it and it helps you be consistent, fine; if you hate it, you're giving up nothing by eating first. The authors' own practical pick is protein before cardio — it may protect muscle, slightly raises post-exercise burn, and doesn't blunt fat use the way carbohydrate does. They also advise against fasted sessions longer than 60 minutes because of protein loss.","what_it_doesnt_mean": "It doesn't prove fasted cardio is useless — it proves it's not better in the populations studied, who were mostly untrained, overweight, or young women on short trials. The authors hold open a door for very lean competitors, but that's a hypothesis they're explicit about. And none of this is about fasted lifting, high-intensity work, or intermittent fasting as a diet.","questions_raised": []},"translation": ["Fasted vs fed cardio, matched calories, 4 weeks: ~1.1 kg vs ~0.7 kg fat lost, not a significant difference.","Fasted: more fat burned in the session; fed: more burned afterwards. Net: about the same.","If fasted: keep it under 60 min and low-to-moderate intensity. Or have 25 g protein first."],"glossary_candidates": [{"term": "Fasted cardio","definition": "Aerobic exercise done after an overnight fast, before eating.","confidence_term_is_new": "likely"},{"term": "Fat oxidation vs fat loss","definition": "Fat oxidation is fat burned right now; fat loss is the change in body fat over time, which depends on total energy balance.","confidence_term_is_new": "likely"},{"term": "Intramuscular triglyceride","definition": "Fat stored inside muscle fibres; a fuel for moderate exercise, especially when fasted.","confidence_term_is_new": "likely"},{"term": "Meta-analysis","definition": "A study that pools the results of many studies to get a more reliable overall answer.","confidence_term_is_new": "likely"},{"term": "Effect size","definition": "How big a difference is, independent of whether it's statistically significant; \"trivial\" means too small to matter.","confidence_term_is_new": "likely"},{"term": "Energy balance / calorie deficit","definition": "Calories in minus calories out; fat loss over time requires a sustained deficit.","confidence_term_is_new": "likely"},{"term": "Protein-enhanced cardio","definition": "Cardio done after a protein-only feed (e.g. 25 g whey or casein).","confidence_term_is_new": "likely"}],"charts": [{"template": "before_after_bars","title": "Schoenfeld 2014: fat mass, fasted vs fed cardio","series": [{"label": "Fasted","before": 16.5,"after": 15.4},{"label": "Fed","before": 15.7,"after": 15.0}],"units": "kg fat mass","approximate": false,"note": "20 women, 4 weeks, hypocaloric diet; no significant difference between groups. Review authors' reporting of Schoenfeld 2014."},{"template": "before_after_bars","title": "Schoenfeld 2014: % body fat, fasted vs fed cardio","series": [{"label": "Fasted","before": 26.3,"after": 25.0},{"label": "Fed","before": 24.8,"after": 24.1}],"units": "% body fat","approximate": false,"note": "No significant difference between groups. Review authors' reporting of Schoenfeld 2014. Population: review; pooled n ≈ 96 for body-composition outcomes (Hackett & Hagstrom)."}],"verification_notes": ["All numbers are the review authors' reporting of cited studies; not verified against originals.","Vieira 27/273, p = 0.91: pp.1–2","Van Proeyen +22%: p.2","IMCT ~60%: p.2","Aird 46 studies: p.2","Trabelsi all values: p.3","Hackett & Hagstrom 5/96/60M/36F: p.3","Schoenfeld values, 1.8 g/kg, 60 min 3×/wk: pp.3–4","14 g/h nitrogen: p.4","Gieske design and results: pp.4–5","Practical applications, 60-min limit: pp.5–6","Conflicts/funding: p.6."]}$ke$::jsonb, now());
INSERT INTO knowledge_entries (slug, status, entry, published_at) VALUES
  ('gastin-1995', 'published', $ke${"id": "gastin-1995","slug": "gastin-1995","source_pdf": "accumulated_oxygen_deficit_during_supramaximal_16-2.pdf","shape": "comparison","document_type": "journal article","meta_analysis": false,"key_findings": ["Anaerobic capacity (accumulated oxygen deficit) came out the same whether riders went all-out or rode to exhaustion at a fixed supramaximal load: 42.0–44.1 ml/kg across study 1's three tests.","The all-out tests hit far higher peaks (9.6 and 11.9 W/kg — up to 254% of VO2max power) yet drew the same anaerobic total.","Agreement between any two tests averaged ~4–5 ml/kg per rider (ranges 0–13.2) — a usable estimate, not a precise one.","Anaerobic capacity showed no relationship to fast-twitch fibre percentage (r = −0.05).","The longer the test, the more aerobic it was: 51% aerobic in the 62-second all-out vs 76% in the ~3-minute constant ride."],"header": {"title_plain": "A 60–90 s all-out cycling test gave the same anaerobic-capacity estimate (accumulated oxygen deficit) as riding to exhaustion at a fixed supramaximal workload.","setup_plain": "Two studies in two labs. In the first, nine active men rode to exhaustion at 110% and 125% of VO2max and did a 62-second all-out isokinetic test. In the second, twelve men — six untrained, six endurance trained — rode to exhaustion at 110% and did a 90-second all-out test with falling resistance. Accumulated oxygen deficit was measured in every test and compared across them.","citation": {"title": "Accumulated oxygen deficit during supramaximal all-out and constant intensity exercise","authors": "Gastin PB, Costill DL, Lawson DL, Krzeminski K, McConell GK","year": "1995","journal": "Medicine and Science in Sports and Exercise","volume_issue_pages": "27(2): 255–263","doi": "not printed in source"},"topics": ["anaerobic-capacity","accumulated-oxygen-deficit","aod","supramaximal-exercise","all-out-test","sprint-testing","cycling","testing-protocols","oxygen-uptake","energy-systems","fitness-testing"],"evidence_type": "Two separate method-comparison studies with no training period. Study 1: 9 active men, three supramaximal cycle tests (constant ~110% and ~125% VO2max to exhaustion, and an isokinetic all-out test) in random order. Study 2: 12 subjects (6 untrained, 6 endurance trained; sex not stated), a constant ~110% VO2max test to exhaustion and a 90 s all-out test; order not stated as randomised. No blinding stated. Each test performed once per subject.","confidence": {"level": "preliminary","why": "The hand entry rated this preliminary–moderate; preliminary is chosen because each study is small (n = 9 and n = 12), each test was done once with no test–retest reliability data, AOD is an indirect estimate built on an extrapolated oxygen cost, and 'not significantly different' was not backed by an equivalence test, although the result did replicate across two labs and two ergometers."},"practical_relevance": {"level": "low","why": "A method-validation paper for lab testing; the single practical point is that a 60–90 s all-out effort captures anaerobic capacity about as well as a constant-pace ride to exhaustion, which matters to whoever designs tests rather than to day-to-day programming."},"author_stance": "The study 2 all-out protocol is a modification of a variable-resistance test previously published by the first author's group (Gastin et al., ref 14), so the authors are validating a protocol from their own lab; no other interest is apparent.","funding_and_conflicts": "not stated"},"layer1": {"comparison": {"who": [{"name": "Study 1 (Ball State University, USA)","n": "9","age": "27 ± 1 yr (range 23–35), mean ± SEM","sex": "male","training_status": "\"active\"; \"a fairly heterogeneous group of training backgrounds and sporting pursuits\"; graduate students in the Human Performance Laboratory","other": "Height 181 ± 2 cm (174–191); weight 76 ± 2 kg (69–87); VO2max 57 ± 3 ml·kg−1·min−1 (45–67); fast-twitch fibres in vastus lateralis 48 ± 6% (30–78); efficiency regression slope 11.8 ± 0.2 ml·min−1·W−1, intercept 2.5 ± 0.5 ml·kg−1·min−1, r = 0.996 ± 0.001"},{"name": "Study 2 (Victoria University of Technology, Australia)","n": "12 (6 untrained, 6 endurance trained), pooled a priori","age": "23 ± 1 yr (range 18–30), mean ± SEM","sex": "not stated","training_status": "6 untrained (VO2max 48 ± 1 ml·kg−1·min−1) and 6 endurance trained (VO2max 63 ± 1 ml·kg−1·min−1)","other": "Height 180 ± 2 cm (172–190); weight 72 ± 2 kg (63–81); VO2max 55 ± 3 ml·kg−1·min−1 (44–67); efficiency regression slope 10.9 ± 0.2 ml·min−1·W−1, intercept 7.9 ± 0.3 ml·kg−1·min−1, r = 0.998 ± 0.003; fibre type not measured"}],"conditions": [{"name": "S1 110% constant","description": "Study 1. Seated ride to exhaustion at a preset power output on a Cybex MET 100 ergometer in constant-workrate mode, pedalling ~90 rpm; stopped when the rider could not hold above 80 rpm.","intensity": "Target ~110% VO2max; achieved 107 ± 1% VO2max; mean power 5.0 ± 0.3 W·kg−1","duration": "186 ± 13 s (to exhaustion)","other": "7 min warm-up at 50% VO2max, 5 min rest, rolling start; expired gas in Douglas bags; fingertip blood lactate at 1, 3 and 5 min post"},{"name": "S1 125% constant","description": "Study 1. As above at a higher preset power output.","intensity": "Target ~125% VO2max; achieved 125 ± 2% VO2max; mean power 5.9 ± 0.3 W·kg−1","duration": "94 ± 7 s (to exhaustion)","other": "Same warm-up, gas collection and lactate sampling as above"},{"name": "S1 isokinetic all-out","description": "Study 1. Maximal effort on the Cybex ergometer in isokinetic mode, cadence fixed at 90 rpm; stopped when power (sampled at 0.5 Hz) fell below that equivalent to 95% VO2max.","intensity": "Mean 149 ± 5% VO2max (7.0 ± 0.2 W·kg−1); peak 9.6 ± 0.2 W·kg−1 (206% VO2max); minimum 4.2 ± 0.3 W·kg−1 (92% VO2max)","duration": "62 ± 2 s","other": "Fatigue index 55.5 ± 2.7%; three study-1 tests given in random order, 2–7 d apart"},{"name": "S2 110% constant","description": "Study 2. Seated ride to exhaustion at a constant intensity on a modified Monark 814 friction-loaded ergometer at ~90 rpm; ended voluntarily or by the investigator when power fell below that equivalent to 95% VO2max.","intensity": "Target ~110% VO2max; achieved 109 ± 1% VO2max; mean power 4.8 ± 0.2 W·kg−1","duration": "208 ± 18 s (to exhaustion)","other": "Breath-by-breath gas analysis and power averaged over 5 s intervals"},{"name": "S2 variable all-out","description": "Study 2. 90 s maximal effort on the Monark with variable resistance (modified from Gastin et al., ref 14): 0.095 kg·kg−1 body weight, reduced to 0.075 at 30 s and 0.055 at 60 s; cadence free to vary.","intensity": "Mean 143 ± 5% VO2max (6.4 ± 0.1 W·kg−1); peak 11.9 ± 0.2 W·kg−1 (254% VO2max); minimum 3.9 ± 0.2 W·kg−1 (92% VO2max)","duration": "90 s (fixed)","other": "Fatigue index 66.7 ± 1.9%; order of the two study-2 tests not stated as randomised"}],"design_notes": "Two independent studies run by the first author in separate labs. Before the supramaximal tests, each subject did a VO2max test and a series of submaximal rides (study 1: six to eight 7 min rides from 80 W rising 40 W per ride, 29 ± 2 to 84 ± 2% VO2max, 80–360 W; study 2: five to six 5 min rides at 46 ± 1 to 81 ± 2% VO2max, steady state accepted when VO2 changed by less than 0.6 ml·kg−1 (<50 ml) from the 4th to 5th min). The linear oxygen-cost-versus-power relationship was extrapolated to estimate the oxygen cost of each supramaximal test (Medbø method); AOD = estimated oxygen cost minus measured oxygen uptake. Tests 2–7 d apart at the same time of day, after 24 h of standardised diet and limited activity and at least 4 h fasting. Study 1 used Douglas bags; study 2 breath-by-breath. Study 1 fibre type from a vastus lateralis biopsy (ATPase stain, ~400 fibres). Statistics: study 1 one-way repeated-measures ANOVA with Newman-Keuls post hoc; study 2 two-tailed paired t-test; P < 0.05; data mean ± SEM. Peak blood lactate was not reported for study 2. The authors note AOD variance may be higher than other measures because it is derived from several measures each with its own variance, and that AOD may not be a valid measure of anaerobic capacity at all (with references). No invasive validation of AOD was done. No test–retest reliability data, no equivalence test.","measured": [{"outcome": "Accumulated oxygen deficit (AOD)","unit": "ml·kg−1","values_by_condition": {"S1 110% constant": "43.9 ± 3.0","S1 125% constant": "44.1 ± 1.8","S1 isokinetic all-out": "42.0 ± 2.0","S2 110% constant": "52.1 ± 3.1","S2 variable all-out": "51.2 ± 2.5"},"differed": "no (P > 0.05 within each study)","note": "Primary outcome. Not an equivalence test: 'not significantly different' only."},{"outcome": "Individual between-test difference in AOD","unit": "ml·kg−1","values_by_condition": {"Study 1 (any two tests)": "4.0 ± 0.5 (range 1.3–10.3)","Study 2 (110% vs all-out)": "4.7 ± 1.1 (range 0–13.2)"},"differed": "not tested","note": "Averaged absolute differences between a subject's own tests, reported as mean ± SEM. The paper does not call these coefficients of variation. Greater interindividual variability in the constant-intensity tests (study 1)."},{"outcome": "AOD by training status (study 2)","unit": "ml·kg−1","values_by_condition": {"S2 variable all-out, untrained": "49.9","S2 variable all-out, endurance trained": "52.6","S2 110% constant, untrained": "47.1","S2 110% constant, endurance trained": "57.1"},"differed": "Between groups: no (all-out P = 0.60; constant P = 0.11). Test-by-group pattern: yes (P = 0.04)","note": "Untrained higher AOD in the all-out test (mean difference 2.7 ± 1.1); endurance trained higher in the constant test (4.5 ± 2.8). All 6 untrained had their highest AOD in the all-out test; 4 of 6 trained had theirs in the constant test. Subgroups of 6."},{"outcome": "Exercise intensity achieved","unit": "% VO2max","values_by_condition": {"S1 110% constant": "107 ± 1","S1 125% constant": "125 ± 2","S1 isokinetic all-out": "149 ± 5","S2 110% constant": "109 ± 1","S2 variable all-out": "143 ± 5"},"differed": "yes — study 1: all pairs; study 2: 110% vs all-out","note": "All-out values are means over the test."},{"outcome": "Duration (time to exhaustion for constant tests)","unit": "s","values_by_condition": {"S1 110% constant": "186 ± 13","S1 125% constant": "94 ± 7","S1 isokinetic all-out": "62 ± 2","S2 110% constant": "208 ± 18","S2 variable all-out": "90"},"differed": "yes — study 1: all pairs; study 2: 110% vs all-out","note": "Study 2 all-out duration was fixed by protocol."},{"outcome": "Total work","unit": "J·kg−1","values_by_condition": {"S1 110% constant": "921 ± 73","S1 125% constant": "536 ± 21","S1 isokinetic all-out": "429 ± 17","S2 110% constant": "979 ± 74","S2 variable all-out": "576 ± 12"},"differed": "yes — study 1: 110% vs 125% and 110% vs all-out (125% vs all-out not marked significant); study 2: 110% vs all-out","note": "Extra work in the longer tests attributed to aerobic metabolism."},{"outcome": "Mean power","unit": "W·kg−1","values_by_condition": {"S1 110% constant": "5.0 ± 0.3","S1 125% constant": "5.9 ± 0.3","S1 isokinetic all-out": "7.0 ± 0.2","S2 110% constant": "4.8 ± 0.2","S2 variable all-out": "6.4 ± 0.1"},"differed": "yes — study 1: all pairs; study 2: 110% vs all-out","note": ""},{"outcome": "Peak power (all-out tests only)","unit": "W·kg−1","values_by_condition": {"S1 isokinetic all-out": "9.6 ± 0.2 (206% VO2max)","S2 variable all-out": "11.9 ± 0.2 (254% VO2max)"},"differed": "not tested","note": "Discussion gives study 1 peak as 205% VO2max, results text 206%. Minimum power: 4.2 ± 0.3 (92% VO2max) and 3.9 ± 0.2 (92% VO2max)."},{"outcome": "Fatigue index (all-out tests only)","unit": "%","values_by_condition": {"S1 isokinetic all-out": "55.5 ± 2.7","S2 variable all-out": "66.7 ± 1.9"},"differed": "not tested","note": "Authors attribute the higher study 2 value to higher peak and slightly lower minimum power."},{"outcome": "Aerobic share of total energy (aerobic metabolism)","unit": "%","charted": true,"values_by_condition": {"S1 110% constant": "76 ± 1","S1 125% constant": "59 ± 2","S1 isokinetic all-out": "51 ± 1","S2 110% constant": "74 ± 1","S2 variable all-out": "57 ± 2"},"differed": "yes — study 1: all pairs; study 2: 110% vs all-out","note": ""},{"outcome": "Aerobic work","unit": "J·kg−1","values_by_condition": {"S1 110% constant": "707 ± 63","S1 125% constant": "321 ± 22","S1 isokinetic all-out": "221 ± 11","S2 110% constant": "730 ± 64","S2 variable all-out": "327 ± 10"},"differed": "yes — study 1: 110% vs 125% and 110% vs all-out (125% vs all-out not marked); study 2: 110% vs all-out","note": "Calculated assuming the same work costs 1 mol ATP whether made aerobically or anaerobically (Fig 2 legend)."},{"outcome": "Anaerobic work","unit": "J·kg−1","values_by_condition": {"S1 110% constant": "214 ± 15","S1 125% constant": "215 ± 8","S1 isokinetic all-out": "208 ± 10","S2 110% constant": "249 ± 15","S2 variable all-out": "249 ± 12"},"differed": "no","note": "Calculated, as above."},{"outcome": "Anaerobic energy release, first 30 s (oxygen deficit rate)","unit": "ml·kg−1·s−1","values_by_condition": {"S1 110% constant": "0.60 ± 0.04","S1 125% constant": "0.73 ± 0.05","S1 isokinetic all-out": "1.12 ± 0.06","S2 110% constant": "0.67 ± 0.03","S2 variable all-out": "1.35 ± 0.04"},"differed": "yes — study 1: all pairs; study 2: 110% vs all-out","note": "Fig 3 shows the same data as oxygen deficit in the first 30 s, in ml·kg−1."},{"outcome": "Aerobic energy release, first 30 s (oxygen uptake rate)","unit": "ml·kg−1·s−1","values_by_condition": {"S1 110% constant": "0.42 ± 0.02","S1 125% constant": "0.45 ± 0.02","S1 isokinetic all-out": "0.58 ± 0.03","S2 110% constant": "0.36 ± 0.02","S2 variable all-out": "0.53 ± 0.02"},"differed": "yes — study 1: 110% vs all-out and 125% vs all-out (110% vs 125% not marked); study 2: 110% vs all-out","note": "Oxygen uptake rose faster in the all-out tests."},{"outcome": "Peak blood lactate","unit": "mmol·l−1","values_by_condition": {"S1 110% constant": "16.7 ± 0.6","S1 125% constant": "14.5 ± 0.5","S1 isokinetic all-out": "18.2 ± 1.0","S2 110% constant": "not reported","S2 variable all-out": "not reported"},"differed": "yes — study 1: 110% vs 125% and 125% vs all-out; 110% vs all-out not marked significant","note": ""},{"outcome": "Correlations, study 1 (n = 9)","unit": "r","values_by_condition": {"AOD vs % fast-twitch fibres": "−0.05 (no relationship)","Peak power vs AOD, isokinetic all-out": "0.85","Peak blood lactate vs AOD": "0.64 in 110% test only; not related in the other two","% fast-twitch vs peak lactate": "0.71 (125%), 0.59 (isokinetic all-out)","% fast-twitch vs VO2max": "−0.68","% fast-twitch vs aerobic energy rate, first 30 s": "−0.77 (110%), −0.75 (125%)","% fast-twitch vs anaerobic energy rate, first 30 s": "no relationship in any test"},"differed": "not applicable","note": "Authors say it is hard to tell whether few relationships exist or whether subject number and training status hid them."},{"outcome": "Single-subject example (study 2, Fig 1; VO2max 49.3 ml·kg−1·min−1)","unit": "ml·kg−1","values_by_condition": {"S2 variable all-out": "48.9","S2 110% constant": "47.7"},"differed": "not tested","note": "Difference 1.2 ml·kg−1 for this subject."}]}},"layer2": {"what_it_means": "Across two separate studies, the estimated anaerobic capacity (accumulated oxygen deficit, AOD) came out the same whether riders went all-out or held a fixed supramaximal workload until exhaustion: 43.9, 44.1 and 42.0 ml·kg−1 for the three study-1 tests and 52.1 versus 51.2 ml·kg−1 in study 2. The calculated anaerobic work was also unchanged across tests (208–215 J·kg−1 in study 1, 249 J·kg−1 for both study-2 tests), while total and aerobic work grew with test length: the 110% rides lasted 186–208 s and drew 74–76% of their energy aerobically, against 51–57% for the 62–90 s all-out tests. The practical reading is that a 60–90 s all-out effort exhausts the anaerobic reserve about as fully as a constant-pace ride to failure, while also yielding peak power, mean power and a fatigue index from the same test. It also shows why total work in a long sprint test partly reflects aerobic fitness rather than anaerobic capacity alone. Individual results were less consistent than the averages: a rider's AOD differed between tests by 4.0 ml·kg−1 on average in study 1 and 4.7 ml·kg−1 in study 2, with differences up to 13.2 ml·kg−1.","what_it_doesnt_mean": "This does not show the two test types are interchangeable for an individual. The comparison found no significant difference; no equivalence test was run, and individual differences reached 10.3 and 13.2 ml·kg−1. In study 2, untrained subjects tended to score higher on the all-out test and endurance-trained subjects on the constant test, though each subgroup had only six people. Samples were small (9 and 12), study 1 was young active men, study 2's sex is not stated, and nobody was older, female by report, or a trained sprinter. Each test was performed once, so day-to-day reliability is unknown. AOD is an indirect estimate: it depends on extrapolating oxygen cost from submaximal rides, assumes efficiency holds above VO2max, and the authors themselves cite work questioning whether AOD validly measures anaerobic capacity. Results apply to seated cycling on two specific lab ergometers, not to running, rowing or field tests, and the paper says nothing about training anaerobic capacity.","questions_raised": []},"translation": ["A 60–90 s all-out bike test gave an anaerobic-capacity estimate not significantly different from riding to failure at about 110–125% of VO2max (42.0 vs 43.9–44.1 ml/kg in one study, 51.2 vs 52.1 ml/kg in the other).","Riding to failure at about 110% lasted 186–208 s and did more total work (921–979 vs 429–576 J/kg), but anaerobic work did not differ; the extra was aerobic."],"glossary_candidates": [{"term": "Accumulated oxygen deficit (AOD)","definition": "The gap between the oxygen a hard effort would need and the oxygen actually used, added up over the effort. Used as an estimate of how much energy came from anaerobic sources.","confidence_term_is_new": "likely"},{"term": "Supramaximal exercise","definition": "Work at an intensity above the power that produces VO2max, so it cannot be supplied by aerobic metabolism alone and can only be held briefly.","confidence_term_is_new": "likely"},{"term": "Anaerobic capacity","definition": "The total amount of energy a person can produce without oxygen (from phosphocreatine and glycolysis) before that supply is used up.","confidence_term_is_new": "unsure"},{"term": "Constant-intensity test (to exhaustion)","definition": "A test in which the workload is fixed in advance and the rider holds it until they can no longer keep the required cadence.","confidence_term_is_new": "likely"},{"term": "All-out test","definition": "A test in which the athlete goes as hard as possible from the start for a set time or until power drops below a cut-off, so power is high early and fades.","confidence_term_is_new": "unsure"},{"term": "Isokinetic ergometer","definition": "An exercise machine that holds cadence at a fixed speed (here 90 rpm) however hard the rider pushes, so only the force and power change.","confidence_term_is_new": "likely"},{"term": "Wingate test","definition": "A standard 30 s all-out cycling test against a fixed resistance set from body weight, used to measure peak and mean anaerobic power.","confidence_term_is_new": "unsure"},{"term": "Fatigue index","definition": "How much power falls during an all-out test, from the peak to the minimum, expressed as a percentage of the peak.","confidence_term_is_new": "likely"},{"term": "Blood lactate (peak)","definition": "The highest lactate concentration measured in blood after a hard effort; a rough marker of how much glycolysis was used.","confidence_term_is_new": "unsure"},{"term": "VO2max","definition": "The highest rate at which a person can take up and use oxygen during exercise, usually in ml per kg body weight per minute.","confidence_term_is_new": "unsure"},{"term": "Efficiency relationship (oxygen cost extrapolation)","definition": "A straight line linking power output to oxygen use, built from several easier rides and extended upward to estimate the oxygen a supramaximal effort would need.","confidence_term_is_new": "likely"},{"term": "SEM (standard error of the mean)","definition": "A measure of how precisely a group average is known; it is smaller than the spread between individuals, so ± SEM values look tighter than the real person-to-person variation.","confidence_term_is_new": "likely"},{"term": "Correlation coefficient (r)","definition": "A number from −1 to 1 describing how closely two measures rise or fall together; 0 means no straight-line relationship.","confidence_term_is_new": "unsure"},{"term": "Fast-twitch fibre percentage (muscle biopsy)","definition": "The share of fast-twitch fibres in a small muscle sample removed with a needle, here from the outer thigh (vastus lateralis).","confidence_term_is_new": "unsure"},{"term": "Douglas bag / breath-by-breath gas analysis","definition": "Two ways to measure oxygen uptake: collecting expired air in large bags for analysis, or analysing each breath continuously with a metabolic cart.","confidence_term_is_new": "likely"}],"charts": [{"template": "values_by_condition","title": "Accumulated oxygen deficit was similar in every test","series": [{"label": "AOD (mean)","values": [{"condition": "S1 110% constant","value": 43.9},{"condition": "S1 125% constant","value": 44.1},{"condition": "S1 isokinetic all-out","value": 42.0},{"condition": "S2 110% constant","value": 52.1},{"condition": "S2 variable all-out","value": 51.2}]}],"units": "ml·kg−1","approximate": false,"note": "Means from Table 2 (± SEM 1.8–3.1). No significant difference within either study. Compare within a study only; studies used different subjects and ergometers."},{"template": "stacked_share","title": "Longer tests drew more of their energy aerobically","series": [{"label": "S1 110% constant","parts": [{"name": "Anaerobic","value": 24},{"name": "Aerobic","value": 76}]},{"label": "S1 125% constant","parts": [{"name": "Anaerobic","value": 41},{"name": "Aerobic","value": 59}]},{"label": "S1 isokinetic all-out","parts": [{"name": "Anaerobic","value": 49},{"name": "Aerobic","value": 51}]},{"label": "S2 110% constant","parts": [{"name": "Anaerobic","value": 26},{"name": "Aerobic","value": 74}]},{"label": "S2 variable all-out","parts": [{"name": "Anaerobic","value": 43},{"name": "Aerobic","value": 57}]}],"units": "% of total energy","approximate": false,"note": "Aerobic % from Table 2; anaerobic share is 100 minus the printed aerobic %, not a separately printed value."},{"template": "population_card","title": "Who was tested","series": [{"n": "21 across two studies (study 1: 9; study 2: 12)","sex_split": "Study 1: 9 men; study 2: not stated","age": "Study 1: 27 ± 1 yr (23–35); study 2: 23 ± 1 yr (18–30)","status": "Study 1: active, mixed training backgrounds (VO2max 57 ± 3 ml·kg−1·min−1); study 2: 6 untrained + 6 endurance trained (VO2max 48 ± 1 and 63 ± 1)","other": "Seated cycling on lab ergometers; each test done once"}],"units": "","approximate": false,"note": "Values mean ± SEM (range)."}],"verification_notes": ["Citation (authors, Med Sci Sports Exerc 27(2): 255–263, 1995), received Dec 1993, accepted Aug 1994; no DOI printed: p.255 (abstract citation line and footer)","Two independent studies, labs (Ball State, Victoria University of Technology), ethics, tests 2–7 d apart, standardised diet/activity, 4 h fasted: p.256 Methods","Study 1: nine active male subjects, heterogeneous training backgrounds; graduate students: p.256 Study 1","Subject characteristics for both studies (age, height, weight, VO2max, % FT fibres, slope, intercept, r, ranges): p.256 Table 1","Study 2: twelve subjects, 6 untrained and 6 endurance trained, VO2max 48 ± 1 and 63 ± 1; pooled a priori; sex not stated anywhere in the paper: p.257 Study 2","Study 1 equipment and protocol (Cybex MET 100, 90 rpm, 7 min submax rides from 80 W +40 W, 29 ± 2 to 84 ± 2% VO2max, 80–360 W, Douglas bags, random order, 7 min warm-up at 50% VO2max, 5 min break, termination rules <80 rpm and <95% VO2max at 0.5 Hz, lactate at 1, 3, 5 min): p.256","Fibre typing (vastus lateralis biopsy, ATPase, ~400 fibres): p.256–257","Study 2 equipment and protocol (Monark 814, 10 Hz sampling, 5 min rides at 46 ± 1 to 81 ± 2% VO2max, steady-state criterion <0.6 ml·kg−1 (<50 ml), resistance 0.095 → 0.075 at 30 s → 0.055 kg·kg−1 BW at 60 s, 90 s duration, termination at <95% VO2max, 5 s averaging): p.257","Statistics (StatView II/SuperANOVA, P < 0.05, mean ± SEM, repeated-measures ANOVA + Newman-Keuls for study 1, two-tailed t-test for study 2): p.257 Statistics","All condition values for intensity, duration, work, power, AOD, aerobic %, aerobic and anaerobic work, first-30-s anaerobic and aerobic energy release, peak blood lactate, and significance markers: p.258 Table 2","AOD headline values 43.9, 44.1, 42.0 and 52.1, 51.2 ml·kg−1, P > 0.05: p.255 Abstract; p.258 Table 2","Study 1 individual AOD difference 4.0 ± 0.5 ml·kg−1 (range 1.3–10.3), greater variability in constant tests: p.258 Results","Study 1 all-out peak 9.6 ± 0.2 W·kg−1 (206% VO2max), minimum 4.2 ± 0.3 (92%), fatigue index 55.5 ± 2.7%, mean 7.0 ± 0.2 (149%): p.258 Results","Study 1 correlations (AOD vs FT r = −0.05; FT vs peak lactate 0.71 and 0.59; lactate vs AOD 0.64 in 110% only; FT vs VO2max −0.68; FT vs first-30-s aerobic rate −0.77 and −0.75; no FT vs anaerobic rate; peak power vs AOD 0.85): p.258–259 Results","Study 2 AOD 51.2 vs 52.1, individual difference 4.7 ± 1.1 ml·kg−1 (range 0–13.2): p.259 Results","Single subject example (VO2max 49.3; AOD 48.9 all-out, 47.7 at 110%; difference 1.2): p.258 Fig 1 legend; p.259 Results","Study 2 subgroup AOD (all-out 49.9 vs 52.6, P = 0.60; constant 47.1 vs 57.1, P = 0.11; P = 0.04 for test comparison; 2.7 ± 1.1 and 4.5 ± 2.8; all 6 untrained highest in all-out, 4 of 6 trained highest in constant): p.259 Results","Study 2 all-out mean 6.4 ± 0.1 W·kg−1 (143%), peak 11.9 ± 0.2 (254%), minimum 3.9 ± 0.2 (92%): p.259 Results; fatigue index 66.7 ± 1.9%: p.260","Aerobic/anaerobic work split and 1 mol ATP assumption: p.259 Fig 2; first-30-s oxygen deficit and uptake: p.259 Fig 3 (values used here are from Table 2, not read from figures)","Discussion figures 205% and 254% peak, 107%/125%/109% constant intensities; discrepancy 205% (p.260) vs 206% (p.258) noted: p.260","Authors' limitations: AOD variance compounded from multiple measures; AOD may not be a valid measure of anaerobic capacity; few correlations possibly due to subject number and training status; possible efficiency error from variable pedal rate in study 2; individual test specificity: p.260–261","Conclusion that an all-out protocol gives a valid estimate of maximal AOD; 60–90 s suggestion; endurance trained may suit a longer constant test: p.262","Funding: no funding or conflict statement printed; acknowledgments only; correspondence address Victorian Institute of Sport: p.262","Own-lab protocol (ref 14, Gastin et al. 1991, variable resistance loadings): p.257 and p.262 references"]}$ke$::jsonb, now());
INSERT INTO knowledge_entries (slug, status, entry, published_at) VALUES
  ('gastin-2001', 'published', $ke${"id": "gastin-2001","slug": "gastin-2001","source_pdf": "Energy_System_Interaction_and_Relative_Contribution_.pdf","shape": "review","document_type": "journal article","meta_analysis": false,"key_findings": ["A 10-second all-out effort is 94% anaerobic — but by 75 seconds the split is already 50/50 (±10%).","By 4 minutes of maximal work, aerobic metabolism supplies ~79% of the energy.","Inside any effort over ~30 seconds, the second half runs mostly on oxygen: a 90-second sprint is 73% aerobic in seconds 30–60 and 91% in seconds 60–90.","Even the 30-second Wingate test is 16–33% aerobic (29% by direct muscle measurement).","Repeated sprints lean more aerobic each round — by the tenth 6-second sprint, glycolysis has nearly shut down."],"header": {"title_plain": "Aerobic energy matters much sooner than coaches think: a 75-second all-out effort is already half aerobic","citation": {"title": "Energy System Interaction and Relative Contribution During Maximal Exercise","authors": "Gastin PB","year": "2001","journal": "Sports Med","volume_issue_pages": "31(10): 725–741","doi": "10.2165/00007256-200131100-00003"},"topics": ["energy-systems","aerobic","anaerobic","sprint","middle-distance","wingate","repeated-sprints","conditioning"],"evidence_type": "Review that pools 30+ studies into a summary curve (Table I/II, Fig 2). Prediction interval ~±10%. Pooled summary, not a formal meta-analysis. No funding stated.","confidence": {"level": "moderate","why": "Moderate for the summary table (many studies, consistent methods); conceptual elsewhere."},"practical_relevance": {"level": "high","why": "The duration table changes how coaches classify and condition for efforts of 30 s to 4 min, and repeated sprints become progressively more aerobic."},"author_stance": "none apparent","funding_and_conflicts": "not stated"},"layer1": {"review": {"claim": "Textbook diagrams showing energy systems switching on one after another, with aerobic metabolism arriving late, are wrong. All three systems contribute from the first seconds. The aerobic share of a maximal effort reaches 50% at roughly 75 seconds, not the 2–4 minutes long taught. The old figures came from an \"oxygen debt\" method that over-counted anaerobic energy.","definitions_used": [],"evidence_cited": [{"charted": true,"finding": "Summary table: share of total energy for a maximal effort of 0–10 s","source": "Table II, pooled","numbers": "Anaerobic 94%, aerobic 6%","note": "±~10%"},{"charted": true,"finding": "Summary table: share of total energy for a maximal effort of 0–15 s","source": "Table II, pooled","numbers": "Anaerobic 88%, aerobic 12%","note": "±~10%"},{"charted": true,"finding": "Summary table: share of total energy for a maximal effort of 0–20 s","source": "Table II, pooled","numbers": "Anaerobic 82%, aerobic 18%","note": "±~10%"},{"charted": true,"finding": "Summary table: share of total energy for a maximal effort of 0–30 s","source": "Table II, pooled","numbers": "Anaerobic 73%, aerobic 27%","note": "±~10%"},{"charted": true,"finding": "Summary table: share of total energy for a maximal effort of 0–45 s","source": "Table II, pooled","numbers": "Anaerobic 63%, aerobic 37%","note": "±~10%"},{"charted": true,"finding": "Summary table: share of total energy for a maximal effort of 0–60 s","source": "Table II, pooled","numbers": "Anaerobic 55%, aerobic 45%","note": "±~10%"},{"charted": true,"finding": "Summary table: share of total energy for a maximal effort of 0–75 s","source": "Table II, pooled","numbers": "Anaerobic 49%, aerobic 51%","note": "±~10%"},{"charted": true,"finding": "Summary table: share of total energy for a maximal effort of 0–90 s","source": "Table II, pooled","numbers": "Anaerobic 44%, aerobic 56%","note": "±~10%"},{"charted": true,"finding": "Summary table: share of total energy for a maximal effort of 0–120 s","source": "Table II, pooled","numbers": "Anaerobic 37%, aerobic 63%","note": "±~10%"},{"charted": true,"finding": "Summary table: share of total energy for a maximal effort of 0–180 s","source": "Table II, pooled","numbers": "Anaerobic 27%, aerobic 73%","note": "±~10%"},{"charted": true,"finding": "Summary table: share of total energy for a maximal effort of 0–240 s","source": "Table II, pooled","numbers": "Anaerobic 21%, aerobic 79%","note": "±~10%"},{"finding": "Within a single bout, aerobic becomes the main source by 20–30 s","source": "as reviewed","numbers": "90-s all-out cycle: aerobic share 30% in first 30 s, 73% in 30–60 s, 91% in 60–90 s. 800 m run: 41 / 73 / 76 / 76% per 30-s phase. 1500 m: 57 / 84 / 87 / 88 / 89 / 89%","note": ""},{"finding": "Oxygen uptake rises fast","source": "as reviewed","numbers": "After 30–60 s of hard exercise VO2 can be ~90% of max","note": ""},{"finding": "Wingate (30 s) is not purely anaerobic","source": "as reviewed","numbers": "Aerobic share 16–18% by older assumed-efficiency methods, 23–33% by oxygen-deficit method, 29% by direct muscle measures","note": ""},{"finding": "Repeated sprints lean harder on aerobic","source": "as reviewed","numbers": "Second 30-s sprint after 4 min rest: aerobic share 44%, power −18%, anaerobic ATP −41%, VO2 +19%. Ten 6-s sprints: anaerobic ATP use fell 64%, glycolysis almost shut down by sprint 10","note": "Changes are vs the first sprint."},{"finding": "Peak anaerobic power dwarfs what the aerobic system can sustain","source": "as reviewed","numbers": "Weightlifters produce 10–20× the power that elicits VO2max; sprinters 3–5×; maximal anaerobic : sustainable aerobic ratio ~2.0–2.6","note": ""},{"finding": "PCr fires instantly but fades within seconds; glycolysis takes over by ~5 s","source": "as reviewed","numbers": "Each can make ATP at 6–9 mmol/kg dry muscle/s; together ~15 over the first 6 s, half from PCr. PCr rate is maximal immediately and falls after 1.3 s; glycolysis peaks after ~5 s. Resting ATP ~25, PCr 70–80 mmol/kg dm; ATP never drops >30–40%; PCr can be nearly emptied. ATP-PCr provides 20–30% of anaerobic energy in a 2–3 min effort","note": ""},{"finding": "Coaches disagree with the data","source": "as reviewed","numbers": "Eight coaches/scientists put the aerobic share of an 800 m at 35–65%; studies say 55–65%","note": ""},{"finding": "Old textbook estimates","source": "as reviewed","numbers": "Equal contribution at 2 min (Åstrand), 3–4 min (Fox/Mathews) — based on oxygen-debt, now discredited","note": ""}],"recommendations_made": [],"untested_or_contested": "Anaerobic energy can't be measured directly in whole-body exercise; all estimates are indirect (oxygen deficit, biopsies, models) and may under-count. Efficiency may change at supramaximal intensities. Training status made only small differences in the pooled data."}},"layer2": {"what_it_means": "Anything longer than about a minute at max effort is mostly aerobic, and anything longer than 20–30 seconds is already mostly aerobic by its second half. An 800 m run, a 90-second all-out bike, a 2-minute AMRAP: these are aerobic events with an anaerobic start, not the reverse. The practical corollary is that aerobic fitness determines performance in \"anaerobic\" work far more than old charts suggest, and that repeated sprints become progressively more aerobic as the anaerobic systems run down — by the tenth 6-second sprint, glycolysis has nearly stopped and the oxidative system is doing the work.","what_it_doesnt_mean": "This doesn't say the anaerobic systems are unimportant — in the first 10 seconds they supply 94% of energy, and in a 30-second sprint still 73%. It doesn't give the time course of each system within a bout (the summary curve is cumulative). The ±10% band is wide, and every anaerobic estimate is indirect. \"Aerobic\" here means oxygen use by the working muscle, not \"easy\": the aerobic system at 90% of max is hard work.","questions_raised": []},"translation": ["10 s max effort: ~94% anaerobic. 30 s: ~73%. 60 s: ~55%. 75 s: 50/50. 2 min: ~63% aerobic. 4 min: ~79% aerobic.","Within any effort over ~30 s, the second half runs mainly on oxygen.","Repeated sprints: each one is more aerobic than the last."],"glossary_candidates": [{"term": "ATP","definition": "The molecule muscles spend for every contraction; it's stored in tiny amounts and must be remade constantly.","confidence_term_is_new": "likely"},{"term": "Phosphocreatine (PCr)","definition": "A fast backup store that remakes ATP in the first seconds of hard effort; nearly empty after ~10–20 s of all-out work.","confidence_term_is_new": "likely"},{"term": "Glycolysis","definition": "Breaking down carbohydrate without oxygen to make ATP quickly; produces lactate.","confidence_term_is_new": "likely"},{"term": "Aerobic (oxidative) system","definition": "Making ATP with oxygen from carbohydrate and fat; slower to start but almost unlimited capacity.","confidence_term_is_new": "likely"},{"term": "Oxygen debt","definition": "The old idea that extra oxygen breathed after exercise \"repays\" anaerobic energy; discredited as a measure.","confidence_term_is_new": "likely"},{"term": "Muscle biopsy","definition": "A small sample of muscle taken with a needle to measure its contents.","confidence_term_is_new": "likely"}],"charts": [{"template": "stacked_share","title": "Anaerobic vs aerobic share by duration of maximal effort","series": [{"label": "0–10 s","parts": [{"name": "anaerobic","value": 94},{"name": "aerobic","value": 6}]},{"label": "0–15 s","parts": [{"name": "anaerobic","value": 88},{"name": "aerobic","value": 12}]},{"label": "0–20 s","parts": [{"name": "anaerobic","value": 82},{"name": "aerobic","value": 18}]},{"label": "0–30 s","parts": [{"name": "anaerobic","value": 73},{"name": "aerobic","value": 27}]},{"label": "0–45 s","parts": [{"name": "anaerobic","value": 63},{"name": "aerobic","value": 37}]},{"label": "0–60 s","parts": [{"name": "anaerobic","value": 55},{"name": "aerobic","value": 45}]},{"label": "0–75 s","parts": [{"name": "anaerobic","value": 49},{"name": "aerobic","value": 51}]},{"label": "0–90 s","parts": [{"name": "anaerobic","value": 44},{"name": "aerobic","value": 56}]},{"label": "0–120 s","parts": [{"name": "anaerobic","value": 37},{"name": "aerobic","value": 63}]},{"label": "0–180 s","parts": [{"name": "anaerobic","value": 27},{"name": "aerobic","value": 73}]},{"label": "0–240 s","parts": [{"name": "anaerobic","value": 21},{"name": "aerobic","value": 79}]}],"units": "% of total energy","approximate": false,"note": "Summary table (Table II, pooled); prediction interval ±~10%."},{"template": "values_by_condition","title": "Aerobic share per 30-s phase within a single bout","series": [{"label": "90-s all-out","values": [{"condition": "0–30 s","value": 30},{"condition": "30–60 s","value": 73},{"condition": "60–90 s","value": 91}]},{"label": "800 m","values": [{"condition": "0–30 s","value": 41},{"condition": "30–60 s","value": 73},{"condition": "60–90 s","value": 76},{"condition": "90–120 s","value": 76}]},{"label": "1500 m","values": [{"condition": "0–30 s","value": 57},{"condition": "30–60 s","value": 84},{"condition": "60–90 s","value": 87},{"condition": "90–120 s","value": 88},{"condition": "120–150 s","value": 89},{"condition": "150–180 s","value": 89}]}],"units": "% aerobic","approximate": false,"note": "Phase labels for 800 m and 1500 m are successive 30-s phases as printed (\"per 30-s phase\")."}],"verification_notes": ["All numbers are the review authors' reporting of cited studies; not verified against originals.","Table II and ±10%: p.735","Table I studies: pp.731–733","Table III phases: p.736","20–30 s crossover within bout: p.736","Wingate 16–18 / 23–33 / 29%, second sprint 44%, 6-s sprints 64%: p.730","VO2 90% at 30–60 s: p.730","Power ratios, 10–20×, 3–5×, 2.0–2.6: p.729","ATP/PCr rates and stores: p.730","Coaches 35–65% vs 55–65%: p.734","Old estimates 2 / 3–4 min: pp.727, 735","Funding: not stated."]}$ke$::jsonb, now());
INSERT INTO knowledge_entries (slug, status, entry, published_at) VALUES
  ('gillen-2016', 'published', $ke${"id": "gillen-2016","slug": "gillen-2016","source_pdf": "12_weeks_sprint_interval_.pdf","shape": "intervention","document_type": "journal article","meta_analysis": false,"key_findings": ["Ten minutes of exercise — one minute of it hard — matched 45 minutes of steady cardio: VO2peak +19% in both groups.","Insulin sensitivity rose 53% with sprints and 34% with steady cardio; the no-training group didn't change.","Muscle adaptations matched too: mitochondrial-content marker +48% vs +27%; GLUT4 ~+50% in both.","The control group changed on nothing — the training caused the gains.","Time commitment differed five-fold for the same fitness result."],"header": {"title_plain": "Three 20-second all-out sprints in a 10-minute session, three times a week, raised fitness 19% and improved insulin sensitivity in sedentary men, much as 45 minutes of steady cycling did.","setup_plain": "Twenty-five sedentary men were randomized to twelve weeks of sprint-interval training (three 20-second all-out sprints in a 10-minute session), 45 minutes of steady cycling, or no training, three sessions a week. Fitness, insulin sensitivity and muscle measures were taken before and after.","citation": {"title": "Twelve Weeks of Sprint Interval Training Improves Indices of Cardiometabolic Health Similar to Traditional Endurance Training despite a Five-Fold Lower Exercise Volume and Time Commitment","authors": "Gillen JB, Martin BJ, MacInnis MJ, Skelly LE, Tarnopolsky MA, Gibala MJ","year": "2016","journal": "PLoS ONE","volume_issue_pages": "11(4): e0154075","doi": "10.1371/journal.pone.0154075"},"topics": ["sprint-interval","sit","hiit","interval-training","moderate-continuous-training","steady-state-cardio","time-efficient-training","vo2peak","insulin-sensitivity","mitochondria","cardiometabolic-health","sedentary-beginners"],"evidence_type": "Three-arm controlled training study over 12 weeks: sprint interval training (n = 9), moderate continuous training (n = 10) and non-training control (n = 6), 27 sedentary men enrolled, matched for age, BMI and VO2peak and assigned to groups; not stated as randomised; blinding not stated.","confidence": {"level": "moderate","why": "Has a non-training control group and robust measures (IVGTT, muscle biopsies, lab VO2peak test), but groups are small, assignment is not stated as randomised, and some outcomes were analysed on reduced n."},"practical_relevance": {"level": "high","why": "Gives a specific, short protocol (10 min including warm-up, 3 x 20 s all-out) that produced the same size of VO2peak gain as 45 min of moderate cycling in sedentary men, which bears directly on what a coach can program for time-poor beginners."},"author_stance": "none apparent; the senior author's group has previously published on the same brief SIT protocol (Gillen et al. 2014, ref 17), which this study builds on.","funding_and_conflicts": "Funded by an NSERC operating grant (RGPIN/227858-2010) and an internally sponsored McMaster University research grant to MJG; JBG, MJM and LES held NSERC scholarships/fellowships. Authors declare no competing interests."},"layer1": {"intervention": {"groups": [{"name": "Sprint interval training (SIT)","protocol": "Stationary bike (electronically braked ergometer). 2 min warm-up at 50 W; 3 x 20 s 'all-out' sprints against 0.05 kg/kg body mass (~500 W), with 2 min easy cycling at 50 W between sprints; 3 min cool-down at 50 W. 10 min total, 1 min of hard work per session. Loads adjusted to keep relative intensity as fitness rose.","per_week": "3 sessions (lead-in: 1 session in week 1, 2 in week 2; week 7 two sessions replaced by mid-training testing); 31 ± 1 sessions completed","n_enrolled": "10 (one dropout for reasons unrelated to the study)","n_analysed": "9 (8 for blood analyses)","age": "27 ± 7 y","sex": "male","training_status": "sedentary (IPAQ score < 600 MET-minutes per week)","other": "Weight 84 ± 23 kg; BMI 27 ± 5 kg/m2; VO2peak 32 ± 7 ml/kg/min. Mean HR over sessions 79 ± 4% HRmax; mean RPE 16 ± 1 (Borg 6-20); ~60 kJ work per session."},{"name": "Moderate-intensity continuous training (MICT)","protocol": "Stationary bike. 2 min warm-up at 50 W; 45 min continuous cycling at ~70% of maximal heart rate (~110 W; target band 64-76% HRmax); 3 min cool-down at 50 W. 50 min total. Loads adjusted to keep relative intensity as fitness rose.","per_week": "3 sessions (same lead-in and week-7 arrangement as SIT); 32 ± 2 sessions completed","n_enrolled": "11 (one dropout for reasons unrelated to the study)","n_analysed": "10 (9 for body composition)","age": "28 ± 9 y","sex": "male","training_status": "sedentary (IPAQ score < 600 MET-minutes per week)","other": "Weight 84 ± 20 kg; BMI 26 ± 6 kg/m2; VO2peak 33 ± 6 ml/kg/min (Table 1; abstract gives 34 ± 6). Mean HR over sessions 71 ± 5% HRmax; mean RPE 13 ± 1; ~310 kJ work per session."},{"name": "Non-training control (CTL)","protocol": "No training. Did not attend the lab during the 12 weeks except for mid-point testing in week 7.","per_week": "0","n_enrolled": "6","n_analysed": "6 (5 for body composition)","age": "26 ± 8 y","sex": "male","training_status": "sedentary (IPAQ score < 600 MET-minutes per week)","other": "Weight 78 ± 25 kg; BMI 25 ± 7 kg/m2; VO2peak 32 ± 7 ml/kg/min."}],"design_notes": "Duration 12 weeks of training. 27 sedentary men, matched for age, BMI and VO2peak and assigned to SIT, MICT or CTL; the paper does not state that assignment was randomised and does not mention blinding. No baseline differences between groups for any variable in Table 1. One dropout in each training group (reasons unrelated to the study). Reduced n for specific outcomes: body composition analysed on n = 9 (MICT) and n = 5 (CTL); blood analyses on n = 8 (SIT), 'due to difficulties during data collection'. All training was on a cycle ergometer in the lab with HR monitored; RPE recorded at sessions 1, 15 and 30. VO2peak measured on a ramp cycle test at baseline, 6 weeks and ~1 week after training. Insulin sensitivity measured by 50-min intravenous glucose tolerance test (IVGTT, CSI index of Tura et al.) after a 10-h fast and a standardised evening meal, 72 h after the last session. Body fat by air-displacement plethysmography (BodPod). Muscle biopsy (vastus lateralis) 96 h after training; citrate synthase and beta-HAD activity, and electron transport chain subunits and GLUT4 by western blot. Diet across the 12 weeks is not described as controlled. Statistics: two-way ANOVA (group x time) with Tukey post hoc; p < 0.05. No equivalence or non-inferiority test between SIT and MICT. Authors' limitations/caveats: mechanisms for the VO2peak gain unknown; time course of muscle remodelling not examined; SIT 'requires a very high level of motivation and is clearly not suited for everyone'; real-world effectiveness and adherence remain contentious; large-scale randomised trials needed.","measured": [{"outcome": "VO2peak (relative)","unit": "ml/kg/min","group": "SIT","before": "32 ± 7","after": "38 ± 8","change": "+19%; ~+12% at 6 weeks","significant": "yes","note": "p < 0.001 vs pre; further rise from 6 to 12 weeks p = 0.007."},{"outcome": "VO2peak (relative)","unit": "ml/kg/min","group": "MICT","before": "34 ± 6","after": "40 ± 8","change": "+19%; ~+12% at 6 weeks","significant": "yes","note": "p < 0.001 vs pre; further rise from 6 to 12 weeks p = 0.005. Table 1 gives baseline 33 ± 6. Absolute change ~6 ml/kg/min in both training groups, ~1.7 METs."},{"outcome": "VO2peak (relative)","unit": "ml/kg/min","group": "CTL","before": "32 ± 7","after": "~32 (approx., from Fig 1)","change": "only small changes","significant": "no","note": "p = 0.43 at 6 weeks, p = 0.99 at 12 weeks."},{"outcome": "VO2peak (absolute)","unit": "L/min","group": "SIT","before": "2.6 ± 0.8","after": "3.0 ± 0.7","change": "+0.4 L/min (calculated from Table 2)","significant": "yes","note": "Time x group p < 0.0001."},{"outcome": "VO2peak (absolute)","unit": "L/min","group": "MICT","before": "2.7 ± 0.5","after": "3.2 ± 0.5","change": "+0.5 L/min (calculated from Table 2)","significant": "yes","note": ""},{"outcome": "VO2peak (absolute)","unit": "L/min","group": "CTL","before": "2.5 ± 0.7","after": "2.5 ± 0.7","change": "none","significant": "no","note": ""},{"outcome": "Max workload on VO2peak test","unit": "W","group": "SIT","before": "243 ± 68","after": "275 ± 50","change": "+32 W (calculated)","significant": "yes","note": "Time x group p < 0.0001."},{"outcome": "Max workload on VO2peak test","unit": "W","group": "MICT","before": "248 ± 30","after": "271 ± 33","change": "+23 W (calculated)","significant": "yes","note": ""},{"outcome": "Max workload on VO2peak test","unit": "W","group": "CTL","before": "219 ± 60","after": "213 ± 52","change": "-6 W (calculated)","significant": "no","note": ""},{"outcome": "Insulin sensitivity index (CSI, from IVGTT)","unit": "x 10^-4 min^-1 [µU/mL]^-1","group": "SIT","before": "4.9 ± 2.5","after": "7.5 ± 4.7","change": "+53%","significant": "yes","note": "p = 0.002. Blood analyses n = 8."},{"outcome": "Insulin sensitivity index (CSI, from IVGTT)","unit": "x 10^-4 min^-1 [µU/mL]^-1","group": "MICT","before": "5.0 ± 3.3","after": "6.7 ± 5.0","change": "+34%","significant": "yes","note": "p = 0.013. Time x group p = 0.039."},{"outcome": "Insulin sensitivity index (CSI, from IVGTT)","unit": "x 10^-4 min^-1 [µU/mL]^-1","group": "CTL","before": "7.4 ± 5.8","after": "7.0 ± 4.9","change": "small","significant": "no","note": "p = 0.64 (Results p.5); abstract gives p = 0.63."},{"outcome": "Glucose area under the curve, 0-50 min of IVGTT","unit": "mmol/L","group": "SIT","before": "303 ± 92","after": "225 ± 75","change": "-78 (calculated)","significant": "yes","note": "p < 0.001. Time x group p = 0.004."},{"outcome": "Glucose area under the curve, 0-50 min of IVGTT","unit": "mmol/L","group": "MICT","before": "321 ± 144","after": "257 ± 103","change": "-64 (calculated)","significant": "yes","note": "p = 0.001."},{"outcome": "Glucose area under the curve, 0-50 min of IVGTT","unit": "mmol/L","group": "CTL","before": "201 ± 52","after": "222 ± 54","change": "+21 (calculated)","significant": "no","note": "p = 0.32."},{"outcome": "Body fat","unit": "%","group": "SIT","before": "30 ± 7","after": "28 ± 8","change": "-2 percentage points (calculated)","significant": "yes","note": "p = 0.011. Time x group p = 0.012."},{"outcome": "Body fat","unit": "%","group": "MICT","before": "27 ± 10","after": "25 ± 10","change": "-2 percentage points (calculated)","significant": "yes","note": "p = 0.011. Body composition n = 9."},{"outcome": "Body fat","unit": "%","group": "CTL","before": "24 ± 6","after": "25 ± 6","change": "+1 percentage point (calculated)","significant": "no","note": "p = 0.12. Body composition n = 5."},{"outcome": "Citrate synthase maximal activity (mitochondrial content marker)","unit": "mmol/kg protein/h","group": "SIT","before": "~3.0 (approx., from Fig 3A)","after": "~4.5 (approx., from Fig 3A)","change": "+48%","significant": "yes","note": "p < 0.0001; higher than CTL post-training (p = 0.03)."},{"outcome": "Citrate synthase maximal activity (mitochondrial content marker)","unit": "mmol/kg protein/h","group": "MICT","before": "~3.5 (approx., from Fig 3A)","after": "~4.4 (approx., from Fig 3A)","change": "+27%","significant": "yes","note": "p = 0.004; higher than CTL post-training (p = 0.03)."},{"outcome": "Citrate synthase maximal activity (mitochondrial content marker)","unit": "mmol/kg protein/h","group": "CTL","before": "~3.6 (approx., from Fig 3A)","after": "~3.6 (approx., from Fig 3A)","change": "small","significant": "no","note": "p = 0.97 (abstract)."},{"outcome": "Electron transport chain proteins (Complex II-70kDa, Complex III-Core 2, COX IV, ATP synthase alpha)","unit": "fold change vs pre","group": "SIT","before": "1.0","after": "~1.3-1.8 (approx., from Fig 3C)","change": "increased","significant": "yes","note": "Complex II p < 0.001; Complex III p < 0.001; COX IV p < 0.001; ATP synthase p = 0.001; all higher than CTL post-training (p < 0.05)."},{"outcome": "Electron transport chain proteins (Complex II-70kDa, Complex III-Core 2, COX IV, ATP synthase alpha)","unit": "fold change vs pre","group": "MICT","before": "1.0","after": "~1.2-1.5 (approx., from Fig 3C)","change": "increased","significant": "yes","note": "Complex II p = 0.02; Complex III p = 0.003; COX IV p = 0.001; ATP synthase p = 0.004; all higher than CTL post-training (p < 0.05)."},{"outcome": "GLUT4 protein content","unit": "arbitrary units (relative to pre)","group": "SIT","before": "1.0 ± 0.6","after": "1.6 ± 0.6","change": "~+50%","significant": "yes","note": "p = 0.001. Time x group p = 0.021."},{"outcome": "GLUT4 protein content","unit": "arbitrary units (relative to pre)","group": "MICT","before": "1.0 ± 0.6","after": "1.5 ± 0.6","change": "~+50%","significant": "yes","note": "p = 0.002."},{"outcome": "GLUT4 protein content","unit": "arbitrary units (relative to pre)","group": "CTL","before": "1.0 ± 0.4","after": "0.9 ± 0.4","change": "little change","significant": "no","note": "p = 0.50."},{"outcome": "Body weight","unit": "kg","group": "SIT / MICT / CTL","before": "84 ± 23 / 84 ± 20 / 78 ± 25","after": "83 ± 22 / 82 ± 20 / 78 ± 23","change": "remained similar in all groups","significant": "no","note": "Time x group p = 0.364."},{"outcome": "BMI","unit": "kg/m2","group": "SIT / MICT / CTL","before": "27 ± 5 / 26 ± 6 / 25 ± 7","after": "26 ± 5 / 26 ± 6 / 25 ± 7","change": "unchanged","significant": "no","note": "Time x group p = 0.334."},{"outcome": "Fasting plasma glucose","unit": "mmol/L","group": "SIT / MICT / CTL","before": "5.0 ± 1.2 / 5.3 ± 0.8 / 5.5 ± 1.6","after": "5.4 ± 0.8 / 5.7 ± 0.9 / 5.4 ± 0.8","change": "no significant change","significant": "no","note": "Time x group p = 0.284. SIT blood n = 8."},{"outcome": "Fasting plasma insulin","unit": "µIU/mL","group": "SIT / MICT / CTL","before": "9.5 ± 5.3 / 10.1 ± 6.0 / 7.5 ± 6.4","after": "7.8 ± 4.1 / 8.4 ± 6.9 / 10.8 ± 13.2","change": "no significant change","significant": "no","note": "Time x group p = 0.135."},{"outcome": "HOMA-IR","unit": "index","group": "SIT / MICT / CTL","before": "2.1 ± 1.3 / 2.4 ± 1.6 / 2.0 ± 2.3","after": "1.9 ± 1.0 / 2.3 ± 2.1 / 2.7 ± 3.7","change": "no significant change","significant": "no","note": "Time x group p = 0.348."},{"outcome": "Glucose disappearance rate (KG, 10-50 min of IVGTT)","unit": "%/min","group": "SIT / MICT / CTL","before": "2.1 ± 0.9 / 2.0 ± 0.9 / 2.1 ± 0.6","after": "2.4 ± 0.8 / 2.1 ± 0.7 / 2.1 ± 0.7","change": "no significant change","significant": "no","note": "Time x group p = 0.576."},{"outcome": "Insulin area under the curve, 10-50 min of IVGTT","unit": "µIU/ml","group": "SIT / MICT / CTL","before": "1231 ± 705 / 1171 ± 591 / 1095 ± 843","after": "1149 ± 844 / 1007 ± 545 / 1158 ± 908","change": "no significant change","significant": "no","note": "Time x group p = 0.353."},{"outcome": "Insulin area under the curve, 0-50 min of IVGTT","unit": "µIU/ml","group": "SIT / MICT / CTL","before": "1515 ± 917 / 1423 ± 712 / 1317 ± 946","after": "1454 ± 1065 / 1223 ± 647 / 1425 ± 1035","change": "no significant change","significant": "no","note": "Time x group p = 0.209."},{"outcome": "Beta-HAD maximal activity (fat-oxidation enzyme)","unit": "mmol/kg protein/h","group": "SIT / MICT / CTL","before": "not printed","after": "not printed","change": "+28% / +17% / -2%","significant": "no","note": "No time x group interaction (p = 0.16)."},{"outcome": "Complex I NDUFA9 protein","unit": "fold change vs pre","group": "SIT / MICT / CTL","before": "1.0","after": "~1.6 / ~1.5 / ~0.7 (approx., from Fig 3C)","change": "not reported in text","significant": "no","note": "No significance markers on this protein in Fig 3C; not listed among the subunits that increased."}]}},"layer2": {"what_it_means": "Ten minutes on a bike with three 20-second all-out sprints, done three times a week for 12 weeks, raised aerobic fitness in sedentary men by the same proportion as 45 minutes of steady cycling at about 70% of maximal heart rate. VO2peak rose 19% in both training groups (sprint group 32 to 38 ml/kg/min; continuous group 34 to 40 ml/kg/min) while the controls did not change. Insulin sensitivity, measured with an intravenous glucose tolerance test, rose 53% after sprint training and 34% after continuous training. Citrate synthase, a marker of how much mitochondria the muscle holds, rose 48% and 27%, and GLUT4, the protein that lets muscle take in glucose, rose about 50% in both. Body fat fell by about two percentage points in both training groups. The sprint group did around 60 kJ of work per session against about 310 kJ, and 1 minute of hard effort inside 10 minutes against 50 minutes. For a time-poor beginner who can tolerate maximal efforts, 3 x 20 s all-out with 2 minutes easy between, three times a week, is a supported way to build aerobic fitness and improve how muscle handles glucose.","what_it_doesnt_mean": "It does not show that the two programmes are equivalent. Both improved compared with control and their results were similar, but the authors ran no equivalence test, and groups of 9 and 10 men are small. The paper does not say assignment was randomised; men were matched and assigned. There were only 6 controls, and blood and body-composition results come from even smaller groups (8 in the sprint group for blood, 9 and 5 for body composition). Everyone was a sedentary man aged about 27; nothing here applies directly to women, older adults, trained athletes or people with diabetes. Body weight, fasting glucose, fasting insulin and HOMA-IR did not change in any group, so the insulin benefit appeared only in the dynamic glucose test. Diet over the 12 weeks is not described as controlled. Every session was supervised in a lab on a bike, sprints were rated about 16 out of 20 for effort, and the authors say this kind of training needs very high motivation and is not suited to everyone. Adherence outside the lab was not tested.","questions_raised": []},"translation": ["Protocol: on a bike, 2 min easy warm-up, then 3 x 20 s flat-out sprints with 2 min easy pedalling between, then 3 min easy cool-down: 10 min total, 3 times a week for 12 weeks.","Comparison group: 45 min steady cycling at about 70% of max heart rate (50 min with warm-up and cool-down), 3 times a week.","Result: VO2peak went up 19% in both groups (about 6 ml/kg/min), even though the sprint group did 1 minute of hard work per session.","Insulin sensitivity rose 53% with sprints and 34% with steady cycling; body weight did not change in either group."],"glossary_candidates": [{"term": "VO2peak","definition": "The highest rate of oxygen use reached in an all-out exercise test, a standard measure of aerobic fitness, usually given in millilitres per kilogram of body weight per minute.","confidence_term_is_new": "unsure"},{"term": "Sprint interval training (SIT)","definition": "Short bursts of all-out effort (here 20 seconds) separated by easy recovery; a subset of high-intensity interval training.","confidence_term_is_new": "unsure"},{"term": "Moderate-intensity continuous training (MICT)","definition": "Steady exercise held at a moderate effort for a long block, such as 45 minutes of cycling at about 70% of max heart rate.","confidence_term_is_new": "likely"},{"term": "Insulin sensitivity","definition": "How strongly the body responds to insulin by clearing sugar from the blood; higher sensitivity means less insulin is needed for the same effect.","confidence_term_is_new": "unsure"},{"term": "Intravenous glucose tolerance test (IVGTT)","definition": "A test in which sugar is given directly into a vein and blood is sampled repeatedly to see how quickly the body clears it and how much insulin it releases.","confidence_term_is_new": "likely"},{"term": "CSI (insulin sensitivity index)","definition": "A number calculated from a 50-minute IVGTT that summarises insulin sensitivity; higher is better.","confidence_term_is_new": "likely"},{"term": "HOMA-IR","definition": "An estimate of insulin resistance worked out from a single fasting blood glucose and insulin value; higher means more resistant.","confidence_term_is_new": "likely"},{"term": "Area under the curve (AUC)","definition": "The total amount of something (here blood glucose or insulin) over the length of a test, rather than its value at one moment.","confidence_term_is_new": "likely"},{"term": "Citrate synthase","definition": "An enzyme found inside mitochondria; how active it is in a muscle sample is used as a marker of how much mitochondria the muscle has.","confidence_term_is_new": "likely"},{"term": "Mitochondria","definition": "The parts of a cell that use oxygen to produce energy; more of them means muscle can do more aerobic work.","confidence_term_is_new": "unsure"},{"term": "Beta-HAD","definition": "An enzyme in the pathway muscle uses to burn fat; its activity is used as a marker of fat-burning capacity.","confidence_term_is_new": "likely"},{"term": "GLUT4","definition": "A protein that moves sugar from the blood into muscle cells; more of it helps muscle take up glucose.","confidence_term_is_new": "likely"},{"term": "Electron transport chain","definition": "The set of protein complexes inside mitochondria that use oxygen to make usable energy; their amount is another marker of mitochondrial content.","confidence_term_is_new": "likely"},{"term": "Muscle biopsy","definition": "A small piece of muscle (here about 100 mg from the outer thigh) removed with a needle under local anaesthetic for lab analysis.","confidence_term_is_new": "unsure"},{"term": "Sedentary","definition": "Doing little physical activity; here defined as scoring under 600 MET-minutes per week on a standard activity questionnaire.","confidence_term_is_new": "unsure"},{"term": "MET (metabolic equivalent)","definition": "A unit of exercise intensity where 1 MET is the energy used sitting at rest; 'MET-minutes' multiplies intensity by time.","confidence_term_is_new": "unsure"},{"term": "Control group","definition": "Participants who do not get the training, so that changes from simply being in the study or the passage of time can be separated from the effect of training.","confidence_term_is_new": "unsure"},{"term": "Randomised","definition": "Assigned to groups by chance, which protects against the groups differing in ways the researchers did not measure; this paper says participants were matched and assigned, not randomised.","confidence_term_is_new": "unsure"},{"term": "Statistically significant","definition": "A result unlikely to be due to chance alone by the study's chosen threshold (here p < 0.05); it says nothing on its own about how large or important the effect is.","confidence_term_is_new": "unsure"},{"term": "RPE (rating of perceived exertion)","definition": "A person's own rating of how hard exercise feels; here on the Borg 6-20 scale, where 13 is 'somewhat hard' and 16 is between 'hard' and 'very hard'.","confidence_term_is_new": "unsure"}],"charts": [{"template": "before_after_bars","title": "VO2peak before and after 12 weeks","series": [{"label": "SIT (3 x 20 s, 10 min)","before": 32,"after": 38},{"label": "MICT (45 min steady)","before": 34,"after": 40},{"label": "Control","before": 32,"after": 32}],"units": "ml/kg/min","approximate": true,"note": "SIT and MICT values from the abstract (p.1). Control baseline from Table 1; control post value read from Fig 1 (approx.). Table 1 gives MICT baseline as 33 ± 6. Both training groups +19% (p < 0.001); control p = 0.99."},{"template": "grouped_change_bars","title": "Percent change after 12 weeks, main outcomes","series": [{"group": "SIT","values": [{"label": "VO2peak","value": 19},{"label": "Insulin sensitivity (CSI)","value": 53},{"label": "Citrate synthase","value": 48},{"label": "GLUT4","value": 50},{"label": "Beta-HAD","value": 28}]},{"group": "MICT","values": [{"label": "VO2peak","value": 19},{"label": "Insulin sensitivity (CSI)","value": 34},{"label": "Citrate synthase","value": 27},{"label": "GLUT4","value": 50},{"label": "Beta-HAD","value": 17}]},{"group": "Control","values": [{"label": "VO2peak","value": 0},{"label": "Insulin sensitivity (CSI)","value": -5},{"label": "Citrate synthase","value": 0},{"label": "GLUT4","value": -10},{"label": "Beta-HAD","value": -2}]}],"units": "% change from pre-training","approximate": true,"note": "SIT/MICT percentages as printed (pp.5-8); GLUT4 printed as '~50%' for both. Control percentages are not printed except beta-HAD (-2%): VO2peak, CSI and GLUT4 control values calculated from Table 2 means (2.5 -> 2.5 L/min; 7.4 -> 7.0; 1.0 -> 0.9); control citrate synthase read from Fig 3A (approx.). Beta-HAD change was not significant (interaction p = 0.16)."},{"template": "timeline","title": "Study timeline","series": [{"label": "Baseline testing","start": 0,"end": 0,"note": "VO2peak test; ~5 days later body composition and IVGTT; ~2 days later muscle biopsy; at least 5 days later exercise familiarisation."},{"label": "Lead-in","start": 1,"end": 2,"note": "1 session in week 1, 2 sessions in week 2."},{"label": "Training, 3 sessions per week","start": 3,"end": 12,"note": "SIT 10 min / MICT 50 min per session; loads adjusted to keep relative intensity."},{"label": "Mid-training VO2peak test","start": 7,"end": 7,"note": "Two week-7 sessions replaced by testing; controls attended only this visit during the 12 weeks. VO2peak ~+12% at 6 weeks in both training groups."},{"label": "Post-testing","start": 12,"end": 13,"note": "Body composition and IVGTT 72 h after last session; biopsy 96 h after; VO2peak test ~1 week after training."}],"units": "weeks","approximate": false,"note": "Baseline test day intervals are given in days in the paper and are not placed on a week number; shown at week 0."},{"template": "population_card","title": "Who was studied","series": [{"n": "25 analysed (SIT 9, MICT 10, CTL 6) of 27 enrolled","sex_split": "100% male","age": "27 ± 8 y (abstract); group means 26-28 y","status": "sedentary (IPAQ < 600 MET-min/week)","other": "BMI 26 ± 6 kg/m2; baseline VO2peak 32-33 ml/kg/min; matched for age, BMI and VO2peak; not stated as randomised; reduced n for blood (SIT 8) and body composition (MICT 9, CTL 5)."}],"units": "","approximate": false,"note": ""}],"verification_notes": ["Citation, received/accepted/published dates, DOI 10.1371/journal.pone.0154075, PLoS ONE 11(4): e0154075: p.1 (left column)","Funding (NSERC RGPIN/227858-2010, McMaster internal grant, scholarships): p.1 left column; competing interests none: p.2 left column","Abstract: age 27 ± 8 y, BMI 26 ± 6 kg/m2, n = 9/10/6, SIT ~500 W, 2 min at 50 W, MICT ~110 W at ~70% HRmax, 2 min warm-up and 3 min cool-down: p.1","Abstract: VO2peak +19% both groups, SIT 32 ± 7 to 38 ± 8, MICT 34 ± 6 to 40 ± 8 ml/kg/min, p < 0.001; CSI SIT 4.9 ± 2.5 to 7.5 ± 4.7 (p = 0.002), MICT 5.0 ± 3.3 to 6.7 ± 5.0 (p = 0.013); control p = 0.99 (VO2peak), 0.63 (CSI), 0.97 (CS): p.1","27 sedentary men, IPAQ < 600 MET-minutes/week, matched for age, BMI and VO2peak and 'assigned'; no mention of randomisation; one dropout per training group: p.3 'Subjects and Ethics Approval'","Baseline characteristics by group (age, height, weight, BMI, VO2peak 33/32/32 ml/kg/min, L/min, max workload), no baseline differences: Table 1, p.3","Testing methods: VO2peak ramp test 1 W per 2 s; IVGTT after 10-h fast, standardised meal 561 ± 99 kcal; BodPod; biopsy ~100 mg vastus lateralis: pp.3-4","Familiarisation, MICT target 64-76% HRmax; lead-in 1 session week 1, 2 sessions week 2; week 7 mid-assessment; SIT 3 x 20 s against 0.05 kg/kg body mass with 2 min at 50 W; MICT 45 min at ~70% HRmax; 2-min warm-up, 3-min cool-down; 10- and 50-min sessions; RPE at sessions 1, 15, 30; controls only attended week 7: p.4 '12-week training intervention'","Post-testing timing: body composition and IVGTT 72 h, biopsy 96 h, VO2peak ~1 week after training: p.4 'Post-testing'","CSI formula (Tura et al.), HOMA-IR: p.4","Statistics (two-way ANOVA, Tukey, p < 0.05); reduced n: body composition MICT 9, CTL 5; blood SIT 8: p.5 'Statistics'","Sessions completed 31 ± 1 (SIT) and 32 ± 2 (MICT); mean HR 79 ± 4% and 71 ± 5% HRmax; RPE 16 ± 1 and 13 ± 1; work ~60 and ~310 kJ per session; body mass similar; body fat decreased SIT p = 0.011, MICT p = 0.011, CON p = 0.12: p.5 'Descriptive characteristics of training'","VO2peak ~12% at 6 weeks (p < 0.001), further rise 6 to 12 weeks (p = 0.007 SIT, p = 0.005 MICT), 19% overall; CTL p = 0.43 at 6 wk and p = 0.99 at 12 wk: p.5 'Cardiorespiratory fitness'; Fig 1, p.6","Control VO2peak post value ~32 ml/kg/min: approx., from Fig 1, p.6","CSI +53% SIT (p = 0.002), +34% MICT (p = 0.013), CON p = 0.64; glucose AUC reduced SIT p < 0.001, MICT p = 0.001, CON p = 0.32: p.5 'Indices of glycemic control'; Fig 2, p.7","All pre/post values for weight, BMI, % fat, VO2peak (L/min), max workload, CSI, KG, insulin AUCs, glucose AUC, FPG, FPI, HOMA-IR, GLUT4 and Time/Group/T x G p values: Table 2, p.6","Citrate synthase +48% SIT (p < 0.0001), +27% MICT (p = 0.004), higher than CTL post (p = 0.03); ETC subunit p values: p.6 'Skeletal muscle adaptations'; Fig 3A-C, p.7","Citrate synthase pre/post bar heights and ETC fold changes (incl. NDUFA9): approx., from Fig 3A and Fig 3C, p.7","Beta-HAD +28% SIT, +17% MICT, -2% CTL, interaction p = 0.16; GLUT4 ~50% increase SIT p = 0.001, MICT p = 0.002, CTL p = 0.50: p.8 top","Absolute VO2peak change ~6 ml/kg/min, ~1.7 METs: p.8 'Cardiorespiratory fitness'","Authors' limitations: mechanisms for VO2peak gain unknown (p.9); time course of muscle remodelling not examined (p.10); SIT needs very high motivation and is not suited for everyone, large-scale randomised trials needed (pp.10-11 'Conclusion'); effectiveness/adherence contentious (p.10 'Efficacy versus Effectiveness')","Authors' wording 'to the same extent' / 'as effective as' (p.2 Conclusions, p.8, p.10); no equivalence or non-inferiority test described in Statistics (p.5)","Calculated values (absolute changes, control % changes for VO2peak, CSI, GLUT4) are arithmetic on Table 2 means, labelled 'calculated' in the entry"]}$ke$::jsonb, now());
INSERT INTO knowledge_entries (slug, status, entry, published_at) VALUES
  ('kushmerick-1992', 'published', $ke${"id": "kushmerick-1992","slug": "kushmerick-1992","source_pdf": "Regulation_of_oxygen_consumption_in_fast-_and_slow-twitch_muscle.pdf","shape": "comparison","document_type": "journal article","meta_analysis": false,"key_findings": ["Slow-twitch muscle had about twice the oxygen-using capacity of fast-twitch (estimated max 1.37 vs 0.62 µmol/g/min).","Slow-twitch refilled its phosphocreatine in less than half the time (half-time ~4 vs ~10 min).","Fast-twitch acidified at workloads the slow muscle handled with no pH drop (half-max oxygen at 0.2 vs 1.2 Hz stimulation).","The two fibre types are controlled differently: simple ADP feedback explained the fast muscle but was \"not sufficient\" for the slow one."],"header": {"title_plain": "Slow-twitch muscle refuels twice as fast and has twice the aerobic capacity of fast-twitch — and the two are controlled differently","setup_plain": "Isolated cat muscles — fast-twitch biceps and slow-twitch soleus — were perfused with red cells at 30 °C and stimulated electrically for 15–20 minutes at rates from 0.05 to 2 Hz, then given at least an hour of recovery. Oxygen uptake, phosphocreatine, phosphate, ATP and pH were tracked by NMR through work and recovery.","citation": {"title": "Regulation of oxygen consumption in fast- and slow-twitch muscle","authors": "Kushmerick MJ, Meyer RA, Brown TR","year": "1992","journal": "Am J Physiol","volume_issue_pages": "263 (Cell Physiol 32): C598–C606","doi": "10.1152/ajpcell.1992.263.3.C598"},"topics": ["fibre-type","phosphocreatine","recovery","mitochondria","oxygen-consumption","muscle-energetics","nmr"],"evidence_type": "Ex-vivo animal study (cat muscles, isolated and artificially perfused), 31P-NMR plus oxygen measurements. n = 4 + 3 muscles (NMR), 7 + 7 (oxygen).","confidence": {"level": "moderate","why": "Capped at moderate because this is an ex-vivo animal study (isolated, perfused cat muscle); moderate for the mechanism, not transferable as a prescription."},"practical_relevance": {"level": "low","why": "A mechanism paper that explains why fibre types behave differently; nothing here changes what a coach programs."},"author_stance": "none apparent","funding_and_conflicts": "NIH-funded."},"layer1": {"comparison": {"who": [{"name": "Cat biceps brachii","n": "4 NMR / 7 O2","age": "n/a — cat muscle","sex": "n/a — cat muscle","training_status": "n/a","other": "Fibre type: fast-twitch (FG + FOG). Preparation: isolated, perfused with red cells, 30 °C."},{"name": "Cat soleus","n": "3 NMR / 7 O2","age": "n/a — cat muscle","sex": "n/a — cat muscle","training_status": "n/a","other": "Fibre type: slow-twitch (SO, ~100%). Preparation: same (isolated, perfused with red cells, 30 °C)."}],"conditions": [{"name": "Twitch stimulation","description": "Electrical twitch stimulation; each muscle tested at 2–4 rates.","intensity": "0.05–2 Hz","duration": "15–20 min","other": "Measured: oxygen uptake at steady state, PCr, Pi, ATP and pH by NMR; ADP calculated from the creatine-kinase equilibrium."},{"name": "Recovery","description": "Recovery after each stimulation bout.","intensity": "rest","duration": "≥1 h","other": ""}],"design_notes": "Ex-vivo preparation: cat biceps brachii and soleus isolated and perfused with red cells at 30 °C; 31P-NMR plus oxygen measurements. Electrical twitch stimulation at 0.05–2 Hz for 15–20 min, then ≥1 h recovery; each muscle tested at 2–4 rates. Measured: oxygen uptake at steady state, PCr, Pi, ATP and pH by NMR; ADP calculated from the creatine-kinase equilibrium. Conclusion drawn: simple ADP feedback explains the fast-twitch muscle; it is \"not sufficient\" for the slow-twitch muscle, which shows an unexplained overshoot during recovery.","measured": [{"outcome": "Resting O2 uptake","unit": "µmol/g/min","values_by_condition": {"Biceps (fast)": "0.07","Soleus (slow)": "0.08"},"differed": "no","note": ""},{"outcome": "Maximal O2 uptake, estimated","unit": "µmol/g/min","values_by_condition": {"Biceps (fast)": "0.62 (0.53 reached)","Soleus (slow)": "1.37 (0.84 reached at 2 Hz, ~61% of max)"},"differed": "yes — soleus ~2×","note": ""},{"outcome": "Stimulation rate for half-max O2","unit": "Hz","values_by_condition": {"Biceps (fast)": "0.2 Hz","Soleus (slow)": "1.2 Hz"},"differed": "yes","note": ""},{"outcome": "Mitochondrial density (cited)","unit": "% by volume","values_by_condition": {"Biceps (fast)": "~3% by volume","Soleus (slow)": "~6%"},"differed": "yes","note": "Cited value, not measured in this study."},{"outcome": "PCr recovery half-time after stimulation","unit": "min","values_by_condition": {"Biceps (fast)": "~10 min, simple exponential","Soleus (slow)": "~4 min, not exponential; PCr overshoots to ~50.5% vs 45% resting, Pi undershoots"},"differed": "yes","note": "Pi undershoot 11.8 vs 15.8 (verification notes)."},{"outcome": "ADP rise rest → hardest stimulation","unit": "fold","values_by_condition": {"Biceps (fast)": "~50-fold","Soleus (slow)": "~13-fold"},"differed": "yes","note": ""},{"outcome": "ADP at half-max O2 (K0.5)","unit": "µM","values_by_condition": {"Biceps (fast)": "23 µM (CI 6–39)","Soleus (slow)": "50 µM (34–66)"},"differed": "no (not significant)","note": ""},{"outcome": "Does Pi control respiration?","unit": "","values_by_condition": {"Biceps (fast)": "no","Soleus (slow)": "no"},"differed": "—","note": ""},{"outcome": "pH during 0.5 Hz","unit": "pH","values_by_condition": {"Biceps (fast)": "6.96 → 6.81","Soleus (slow)": "transient rise at onset, then minor change"},"differed": "yes","note": ""},{"outcome": "ATP","unit": "","values_by_condition": {"Biceps (fast)": "unchanged","Soleus (slow)": "unchanged"},"differed": "—","note": ""}]}},"layer2": {"what_it_means": "Slow-twitch muscle isn't just \"more enduring\" in a vague sense: in this preparation it had about twice the oxygen-using capacity, recovered its phosphocreatine in less than half the time (half-time ~4 min vs ~10 min), and barely acidified at workloads that made fast-twitch muscle acidic. That's the physiological basis for the common observation that slow-twitch-dominant athletes recover between efforts quickly and tolerate high-frequency work, and that fast-twitch-dominant athletes need longer rests. It also warns that whole-muscle measurements in humans blend both fibre types, so an individual's recovery curve depends on their fibre mix.","what_it_doesnt_mean": "It's cat muscle, removed from the body and perfused in a magnet at 30 °C, with three or four muscles per group. Twitch stimulation at up to 2 Hz is nothing like a lift or a sprint. The paper is about how respiration is regulated, not about training; the numbers above should not be quoted as human values. The authors themselves end by warning against \"simplistic mechanistic interpretations.\"","questions_raised": []},"translation": ["Slow-twitch muscle: ~2× the aerobic capacity, PCr refilled in ~4 min half-time vs ~10 min for fast-twitch (in this animal preparation).","Fast-twitch muscle acidifies under repeated work; slow-twitch barely does."],"glossary_candidates": [{"term": "Inorganic phosphate (Pi)","definition": "What's released when PCr or ATP is spent; rises during work and is linked to fatigue.","confidence_term_is_new": "likely"},{"term": "PCr recovery half-time","definition": "How long it takes to refill half the spent phosphocreatine after effort — a marker of mitochondrial capacity and a guide to rest intervals.","confidence_term_is_new": "likely"},{"term": "Ex vivo / perfused preparation","definition": "A tissue removed from the animal and kept alive artificially so it can be measured precisely; precise, but not the same as a living body.","confidence_term_is_new": "likely"},{"term": "First-order kinetics","definition": "A simple exponential recovery — the same fraction restored each minute.","confidence_term_is_new": "likely"}],"charts": [{"template": "values_by_condition","title": "Maximal O2 uptake: fast vs slow muscle","series": [{"label": "Maximal O2 uptake, estimated","values": [{"condition": "Biceps (fast)","value": 0.62},{"condition": "Soleus (slow)","value": 1.37}]},{"label": "Maximal O2 uptake, reached","values": [{"condition": "Biceps (fast)","value": 0.53},{"condition": "Soleus (slow)","value": 0.84}]}],"units": "µmol/g/min","approximate": false,"note": "Values from the text/table. O2 uptake vs stimulation rate: biceps plateau ~0.6; soleus still rising at 2 Hz toward ~1.4 (µmol/g/min). Soleus 0.84 reached at 2 Hz, ~61% of max."},{"template": "values_by_condition","title": "PCr recovery half-time after stimulation","series": [{"label": "PCr recovery half-time","values": [{"condition": "Biceps (fast)","value": 10},{"condition": "Soleus (slow)","value": 4}]}],"units": "min","approximate": true,"note": "~10 min (simple exponential) vs ~4 min (not exponential)."},{"template": "concept_curve","title": "PCr recovery curves, fast vs slow muscle","series": [{"label": "Biceps (fast) — half-time 10 min","points": [{"x": 0,"y": 0},{"x": 10,"y": 50},{"x": 20,"y": 75},{"x": 30,"y": 87.5}]},{"label": "Soleus (slow) — half-time ~4 min","points": [{"x": 0,"y": 0},{"x": 4,"y": 50},{"x": 8,"y": 75},{"x": 12,"y": 87.5}]}],"units": "x = minutes after stimulation; y = % of spent PCr restored","approximate": true,"note": "schematic — not measured data. Both curves are simple exponentials computed from the reported half-times (10 min biceps, ~4 min soleus), not traced from the figure. The paper reports the soleus recovery is NOT exponential and overshoots (PCr ~50.5% vs 45% resting at 15–20 min); that overshoot is not drawn."},{"template": "population_card","title": "Who was studied","series": [{"n": "4+3 NMR / 7+7 O2","sex_split": "n/a (animal)","age": "n/a","status": "cat biceps and soleus, ex vivo","other": "isolated, perfused with red cells, 30 °C"}],"units": "","approximate": false,"note": ""}],"verification_notes": ["Muscles, n, prep: C598–C599","Table 1 values: C599","Max O2 0.62/0.53, 1.37/0.84, 61%, half-max 0.2/1.2 Hz, 6%/3%: C600","Half-times 10 / ~4 min, overshoot 50.5 vs 45.0, undershoot 11.8 vs 15.8: C601–C602","ADP 50-/13-fold, K0.5 23 / 50 µM, Pi not controlling: C603","pH 6.96→6.81, soleus alkaline transient: C601–C602","Conclusions and \"simplistic\" warning: C604–C605","Funding: C605."]}$ke$::jsonb, now());
INSERT INTO knowledge_entries (slug, status, entry, published_at) VALUES
  ('malisoux-2006', 'published', $ke${"id": "malisoux-2006","slug": "malisoux-2006","source_pdf": "SSC_training_to_enahnce_power_output_of_single_fibers.pdf","shape": "intervention","document_type": "journal article","meta_analysis": false,"key_findings": ["Every fibre type got bigger (+22–30% size) and more powerful (+25–49% peak power) in eight weeks.","Slow-twitch fibres improved too: +23% size, +19% force, +18% velocity, +25% power.","Hybrid IIa/IIx fibres gained the most power: +49%.","Performance followed: countermovement jump 0.41 → 0.47 m, leg press 1RM 223 → 248 kg, shuttle run 9.98 → 9.62 s.","Unlike 12 weeks of conventional lifting (power up through size and force only), jump training also made fibres faster."],"header": {"title_plain": "Eight weeks of maximal jumping made every muscle fibre type bigger, stronger and faster — including slow-twitch","setup_plain": "Eight recreationally active men did eight weeks of maximal bodyweight jumping — static, countermovement, drop, triple and hurdle jumps, 24 sessions, 5,228 jumps in all. Individual muscle fibres from the thigh were tested for size, force, speed and power before and after. No control group.","citation": {"title": "Stretch-shortening cycle exercises: an effective training paradigm to enhance power output of human single muscle fibers","authors": "Malisoux L, Francaux M, Nielens H, Theisen D","year": "2006","journal": "J Appl Physiol","volume_issue_pages": "100: 771–779","doi": "10.1152/japplphysiol.01027.2005"},"topics": ["plyometrics","stretch-shortening","jump-training","power","hypertrophy","single-fibre","fibre-type"],"evidence_type": "Pre/post intervention, single group, no control, 8 men. Lab single-fibre measurements plus functional tests.","confidence": {"level": "preliminary","why": "Clean mechanistic data, but tiny, uncontrolled and all young men."},"practical_relevance": {"level": "high","why": "Gives a specific bodyweight plyometric protocol (3×/week for 8 weeks) with jump, leg-press and shuttle gains, and shows a fibre-velocity effect conventional lifting has not shown."},"author_stance": "none apparent","funding_and_conflicts": "Funded by a university research fund."},"layer1": {"intervention": {"groups": [{"name": "Plyometric (SSC)","protocol": "Bodyweight jumps, max effort, progressive: static & countermovement jumps, 40-cm drop jumps, double/single-leg triple jumps, hurdle jumps. Sessions 20 → ~45 min","per_week": "3 sessions, 24 total, 5,228 jumps","n_enrolled": "8","n_analysed": "8","age": "23 ±1","sex": "M","training_status": "recreationally active ~3 h/wk; no prior jump training","other": ""}],"design_notes": "No control group. Duration: 8 weeks. Compliance 100%. Biopsies from vastus lateralis 3 days after each test session; 1,115 fibres pre, 1,002 post typed; 60–80 per fibre type tested mechanically. Single-fibre measurements on skinned (dissected, chemically treated) fibres at 15 °C. Comparison the authors draw: 12 weeks of conventional resistance training (Widrick 2002) raised type I and IIa fibre power 30% and 42% through size and force alone, with no change in shortening velocity.","measured": [{"outcome": "Static jump","unit": "m","group": "Plyometric (SSC)","before": "0.40","after": "0.43","change": "+9%","significant": "yes","note": ""},{"outcome": "Countermovement jump","unit": "m","group": "Plyometric (SSC)","before": "0.41","after": "0.47","change": "+13%","significant": "yes","note": ""},{"outcome": "6×5 m shuttle","unit": "s","group": "Plyometric (SSC)","before": "9.98","after": "9.62","change": "−4%","significant": "yes","note": ""},{"outcome": "Leg press 1RM","unit": "kg","group": "Plyometric (SSC)","before": "223","after": "248","change": "+12%","significant": "yes","note": ""},{"outcome": "Fibre cross-sectional area — type I","unit": "µm²","group": "Plyometric (SSC)","before": "4,782","after": "5,862","change": "+23%","significant": "yes","note": ""},{"outcome": "Fibre cross-sectional area — type IIa","unit": "µm²","group": "Plyometric (SSC)","before": "6,511","after": "7,918","change": "+22%","significant": "yes","note": ""},{"outcome": "Fibre cross-sectional area — type IIa/IIx","unit": "µm²","group": "Plyometric (SSC)","before": "5,518","after": "7,167","change": "+30%","significant": "yes","note": ""},{"outcome": "Peak force — type I","unit": "mN","group": "Plyometric (SSC)","before": "0.83","after": "0.99","change": "+19%","significant": "yes","note": ""},{"outcome": "Peak force — type IIa","unit": "mN","group": "Plyometric (SSC)","before": "1.19","after": "1.37","change": "+15%","significant": "yes","note": ""},{"outcome": "Peak force — type IIa/IIx","unit": "mN","group": "Plyometric (SSC)","before": "1.11","after": "1.29","change": "+16%","significant": "yes","note": ""},{"outcome": "Force per area (specific tension) — all fibre types","unit": "","group": "Plyometric (SSC)","before": "unchanged","after": "unchanged","change": "—","significant": "no","note": ""},{"outcome": "Max shortening velocity — type I","unit": "FL/s","group": "Plyometric (SSC)","before": "0.94","after": "1.11","change": "+18%","significant": "yes","note": ""},{"outcome": "Max shortening velocity — type IIa","unit": "FL/s","group": "Plyometric (SSC)","before": "2.94","after": "3.78","change": "+29%","significant": "yes","note": ""},{"outcome": "Max shortening velocity — type IIa/IIx","unit": "FL/s","group": "Plyometric (SSC)","before": "3.58","after": "4.37","change": "+22%","significant": "yes","note": ""},{"outcome": "Peak power — type I","unit": "µN·FL/s","group": "Plyometric (SSC)","before": "12.9","after": "16.1","change": "+25%","significant": "yes","note": ""},{"outcome": "Peak power — type IIa","unit": "µN·FL/s","group": "Plyometric (SSC)","before": "51.2","after": "68.7","change": "+34%","significant": "yes","note": ""},{"outcome": "Peak power — type IIa/IIx","unit": "µN·FL/s","group": "Plyometric (SSC)","before": "49.7","after": "74.2","change": "+49%","significant": "yes","note": ""},{"outcome": "Power per volume — type IIa","unit": "W/l","group": "Plyometric (SSC)","before": "8.11","after": "8.87","change": "+9%","significant": "yes","note": ""},{"outcome": "Power per volume — types I, IIa/IIx","unit": "W/l","group": "Plyometric (SSC)","before": "unchanged","after": "unchanged","change": "—","significant": "no","note": ""},{"outcome": "Fibre-type share — IIa","unit": "%","group": "Plyometric (SSC)","before": "33","after": "41","change": "+8 pts","significant": "no","note": "p = 0.08"},{"outcome": "Fibre-type share — IIx","unit": "%","group": "Plyometric (SSC)","before": "7","after": "3","change": "−4 pts","significant": "no","note": "p = 0.06"},{"outcome": "Fibre-type share — I/IIa hybrids","unit": "%","group": "Plyometric (SSC)","before": "2","after": "5","change": "+3 pts","significant": "yes","note": ""},{"outcome": "Fibre-type share — I","unit": "%","group": "Plyometric (SSC)","before": "30","after": "29","change": "—","significant": "no","note": ""},{"outcome": "Passive stiffness — type IIa/IIx","unit": "kN/m²","group": "Plyometric (SSC)","before": "54.3","after": "66.1","change": "+22%","significant": "yes","note": ""},{"outcome": "Passive stiffness — types I, IIa","unit": "kN/m²","group": "Plyometric (SSC)","before": "unchanged","after": "unchanged","change": "—","significant": "no","note": ""}]}},"layer2": {"what_it_means": "Jump training did more than make these men jump higher. At the level of individual muscle fibres it increased size, force, contraction speed and power across the board — and, unusually, it sped up slow-twitch fibres as well as fast ones. Conventional lifting in comparable studies grows fibres and makes them stronger but doesn't make them faster. So plyometrics appear to train a quality (shortening velocity) that heavy lifting doesn't, and the whole-body results followed: +13% countermovement jump, +12% leg press, faster shuttle run. Three bodyweight sessions a week were enough.","what_it_doesnt_mean": "Eight young, already-active men and no control group: any change over eight weeks of being in a study is attributed to the jumps. The single-fibre measurements are made on dissected, chemically treated fibres at 15 °C — a window into mechanism, not a performance test. The fibre-type shifts didn't reach significance. The authors are explicit that they can't prove the fast contractions caused the faster fibres. Nothing here about women, older adults, or combining plyometrics with lifting, and 5,228 maximal jumps in 8 weeks is a substantial load that was progressed carefully and supervised.","questions_raised": []},"translation": ["Protocol: bodyweight jumps at max effort, 3×/week for 8 weeks, ~20 rising to ~45 min, drop jumps from 40 cm, hurdle and single-leg variants added as tolerated, ~220 jumps per session on average.","Result: vertical jump +9–13%, leg press +12%, 5-m shuttle −4%.","Distinctive effect: fibres got faster, not just bigger — something lifting alone hasn't shown."],"glossary_candidates": [{"term": "Stretch-shortening cycle (SSC)","definition": "A fast lengthening of a muscle immediately followed by a powerful shortening — the mechanism of jumping, bounding, and plyometrics.","confidence_term_is_new": "likely"},{"term": "Plyometrics","definition": "Jump-based training that exploits the stretch-shortening cycle.","confidence_term_is_new": "likely"},{"term": "Countermovement jump","definition": "A vertical jump with a quick dip first; the standard test of lower-body power.","confidence_term_is_new": "likely"},{"term": "Cross-sectional area (CSA)","definition": "The thickness of a muscle or fibre; the main driver of how much force it can produce.","confidence_term_is_new": "likely"},{"term": "Specific tension","definition": "Force divided by fibre size; unchanged here, meaning fibres got stronger by getting bigger, not by improving quality.","confidence_term_is_new": "likely"},{"term": "Shortening velocity (V0)","definition": "How fast a fibre contracts with no load; faster fibres make more power.","confidence_term_is_new": "likely"},{"term": "Hybrid fibres","definition": "Fibres containing more than one myosin type (e.g. IIa/IIx); common and intermediate in properties.","confidence_term_is_new": "likely"},{"term": "Skinned fibre","definition": "A single muscle fibre with its membrane removed so it can be activated and measured in a dish.","confidence_term_is_new": "likely"}],"charts": [{"template": "grouped_change_bars","title": "% change by fibre type after 8 weeks of plyometrics","series": [{"group": "Type I","values": [{"label": "Size","value": 23},{"label": "Force","value": 19},{"label": "Velocity","value": 18},{"label": "Power","value": 25}]},{"group": "Type IIa","values": [{"label": "Size","value": 22},{"label": "Force","value": 15},{"label": "Velocity","value": 29},{"label": "Power","value": 34}]},{"group": "Type IIa/IIx","values": [{"label": "Size","value": 30},{"label": "Force","value": 16},{"label": "Velocity","value": 22},{"label": "Power","value": 49}]}],"units": "% change","approximate": false,"note": "Size = cross-sectional area; force = peak force; velocity = max shortening velocity; power = peak power."},{"template": "before_after_bars","title": "Functional tests before and after","series": [{"label": "Static jump (m)","before": 0.4,"after": 0.43},{"label": "Countermovement jump (m)","before": 0.41,"after": 0.47},{"label": "6×5 m shuttle (s)","before": 9.98,"after": 9.62},{"label": "Leg press 1RM (kg)","before": 223,"after": 248}],"units": "mixed: m, s, kg (see labels)","approximate": false,"note": "% change: SJ +9, CMJ +13, shuttle −4, leg press +12."},{"template": "timeline","title": "Study timeline","series": [{"label": "Pre-tests","start": 0,"end": 0,"note": ""},{"label": "Biopsy","start": 0,"end": 0,"note": "+3 d after pre-tests"},{"label": "Training: 3×/wk","start": 0,"end": 8,"note": "Ramp over first 4 weeks"},{"label": "Post-tests","start": 8,"end": 8,"note": "4 d after last session"},{"label": "Biopsy","start": 8,"end": 8,"note": "+3 d after post-tests"}],"units": "weeks","approximate": false,"note": "Day offsets (+3 d, 4 d) are in each row's note; week positions are schematic."},{"template": "population_card","title": "Who was studied","series": [{"n": "8","sex_split": "100% male","age": "23","status": "recreationally active, no plyometric history","other": "68 kg"}],"units": "","approximate": false,"note": ""}],"verification_notes": ["Subjects: p.772","Programme, 24 sessions, 5,228 jumps, 20→45 min, 40 cm: p.772","Functional results, Table 1: p.775","Fibre counts 1,115/1,002, type shares, Table 2: p.775","CSA, P0, P0/CSA, Table 3: p.776","V0, Table 4: p.776","Power, Table 5: p.777","Stiffness 54.3→66.1: p.776","Widrick comparison: p.778","No causal evidence, mechanisms unknown: p.777","Grant: p.779","15 °C: p.772"]}$ke$::jsonb, now());
INSERT INTO knowledge_entries (slug, status, entry, published_at) VALUES
  ('shulman-2005', 'published', $ke${"id": "shulman-2005","slug": "shulman-2005","source_pdf": "Glycogen_Turnover_Forms_Lactate_during_Exercise.pdf","shape": "review","document_type": "journal article","meta_analysis": false,"key_findings": ["Lactate comes from glycogen turnover feeding fast contractions — not from muscle running out of oxygen (oxygen stays above mitochondrial needs even at VO2max).","Only glycogen is fast enough: PCr swings within ~30 ms of each twitch, and free glucose in muscle (<0.3 mmol) is far too little to supply it.","People whose muscle can't break down glycogen fail even mild exercise — with pH staying high.","Glycogen keeps turning over even when its level is flat; it settles at a lower plateau the harder the exercise.","Carbohydrate feeding delayed exhaustion by about an hour — without slowing the fall of muscle glycogen."],"header": {"title_plain": "A different story about lactate: it's made by glycogen turnover feeding fast contractions, not by running out of oxygen","citation": {"title": "Glycogen Turnover Forms Lactate during Exercise","authors": "Shulman RG","year": "2005","journal": "Exerc Sport Sci Rev","volume_issue_pages": "33(4): 157–162","doi": "not printed in source"},"topics": ["lactate","glycogen","phosphocreatine","fatigue","muscle-energetics","nmr"],"evidence_type": "Review proposing the author's own \"glycogen shunt\" hypothesis, drawing mainly on NMR studies from his lab and a few others. No funding stated.","confidence": {"level": "conceptual","why": "Contested hypothesis — a mechanistic hypothesis, not a settled model."},"practical_relevance": {"level": "low","why": "Mechanism paper; the two coach-usable points (lactate is made in oxygenated muscle; carbohydrate feeding extends time to exhaustion) are background rather than programming changes."},"author_stance": "Proposes his own lab's hypothesis (the \"glycogen shunt\"), drawing mainly on NMR studies from his lab.","funding_and_conflicts": "not stated"},"layer1": {"review": {"claim": "Muscle contractions happen in milliseconds and need ATP on that timescale. PCr refills ATP within a single twitch, but something must refill PCr, and only glycogen breakdown (glycogenolysis) is fast enough. So glycogen is continuously broken down in milliseconds and rebuilt between contractions using oxygen. Lactate is the inevitable by-product of this fast, inefficient route — it is made in fully oxygenated muscle and is not a sign of oxygen shortage. Fatigue at low glycogen may reflect a failing rate of glucose flow through glycogen, not the glycogen level itself.","definitions_used": [],"evidence_cited": [{"finding": "PCr swings within a single twitch","source": "Chung et al., rat muscle, 1-ms NMR","numbers": "PCr falls ~3 µmol/g per twitch (half-time 8 ms) and recovers (half-time 14 ms); whole cycle ~30 ms; ~40× more PCr use per twitch than the old slow method implied; ATP unchanged","note": ""},{"finding": "Glucose can't supply it; glycogen can","source": "—","numbers": "Free glucose + G6P in muscle <0.3 mmol — too little; ~1 µmol/g glycogen per contraction against ~70 µmol/g stores","note": ""},{"finding": "Muscle without glycogen breakdown fails fast","source": "McArdle's disease patients (31P NMR)","numbers": "Resting pH ~7.2 vs 7.02 in controls; during exercise PCr falls much faster, pH stays high, patients can't sustain even mild exercise","note": ""},{"finding": "PCr is not the whole story","source": "Creatine-kinase knockout mice","numbers": "With <1% CK activity: shortening velocity −20%, max power −16%, work −30%, time to sustain −40%; force only ~20% down","note": ""},{"finding": "Glycogen turns over even when its level is flat","source": "13C NMR, human calf, 15/20/25% MVC for hours","numbers": "Glycogen settles at a lower plateau the harder the exercise; labelled glucose is incorporated into glycogen during exercise; 60% depletion after intense toe-lifts, then plateau not baseline","note": ""},{"finding": "Carbohydrate feeding delays fatigue without sparing glycogen","source": "Coyle","numbers": "Fed subjects lasted 1 h longer; glycogen fell at the same rate in both groups; exhaustion at a similar, non-zero glycogen level","note": ""},{"finding": "Oxygen is plentiful in working muscle","source": "Myoglobin NMR","numbers": "Oxygen in working muscle falls with load but stays above mitochondrial needs even at VO2max","note": ""}],"recommendations_made": [],"untested_or_contested": "The twitch-level pH change was not statistically significant. The model rests on measurements that can't yet be made in whole-body human exercise. The author acknowledges the \"normal physiological mechanism\" for lactate production \"has not been found\" — this paper proposes one."}},"layer2": {"what_it_means": "Two ideas a coach can use. First, lactate is not \"the burn from running out of oxygen\"; it's produced whenever muscle needs ATP faster than the oxidative route delivers, which happens in every hard contraction regardless of oxygen supply, and most of it gets re-burned as fuel. Second, hitting the wall at the end of long work may be about the flow rate of carbohydrate through muscle rather than the tank being empty — which is why feeding carbohydrate during long efforts extends time to exhaustion even though glycogen falls at the same rate.","what_it_doesnt_mean": "This is one lab's hypothesis built on rat twitches, a rare genetic disease, knockout mice and NMR of calf muscle at low intensity. It isn't a training study and it doesn't tell you how to train. The \"glycogen shunt\" is not consensus physiology; other models (e.g. Conley et al. in this batch) explain the same lactate without it. For a coach, the safe takeaways are the two above; the mechanism itself is for the curious.","questions_raised": []},"translation": ["Lactate is produced in well-oxygenated muscle; it's fuel, not waste, and not a sign of oxygen debt.","Feeding carbohydrate during long hard sessions extends time to exhaustion (by ~1 h in the cited study)."],"glossary_candidates": [{"term": "Glycogenolysis","definition": "Breaking glycogen down into glucose units to make ATP fast.","confidence_term_is_new": "likely"},{"term": "NMR / MRS","definition": "Magnetic-resonance measurement of chemicals (PCr, ATP, glycogen) inside living muscle without a biopsy.","confidence_term_is_new": "likely"},{"term": "McArdle's disease","definition": "A genetic condition in which muscle can't break down glycogen; sufferers tire and cramp quickly.","confidence_term_is_new": "likely"},{"term": "Lactate shuttle","definition": "The idea (Brooks) that lactate made in one place is carried to another and burned as fuel.","confidence_term_is_new": "likely"},{"term": "Creatine kinase","definition": "The enzyme that moves phosphate between PCr and ATP.","confidence_term_is_new": "likely"},{"term": "MVC","definition": "Maximal voluntary contraction; low-intensity exercise is often set as a % of it.","confidence_term_is_new": "likely"}],"charts": [{"template": "concept_curve","title": "PCr and force within a single twitch","series": [{"label": "PCr (% of resting)","points": [{"x": 0,"y": 100},{"x": 16,"y": 90},{"x": 30,"y": 100}]}],"units": "ms (x); % of resting PCr (y)","approximate": true,"note": "schematic — not measured data. PCr dips ~10% at 16 ms, force peaks at 25 ms, PCr recovered by ~30 ms. Force has no magnitude in the source; mark its peak at x = 25 ms as an annotation only."},{"template": "before_after_bars","title": "Glycogen plateau by exercise intensity (human calf)","series": [{"label": "15% MVC","before": 85,"after": 57},{"label": "20% MVC","before": 72,"after": 50},{"label": "25% MVC","before": 58,"after": 43}],"units": "mM","approximate": true,"note": "Approximate, from Fig 3; start → plateau over ~5–9 h."}],"verification_notes": ["All numbers are the review authors' reporting of cited studies; not verified against originals.","Chung twitch data, 3 µmol/g, 8/14 ms, 40×: p.158 and Fig 1","<0.3 mmol glucose, ~1 and ~70 µmol/g: p.158","McArdle's pH 7.2 vs 7.02: p.159","CK knockout %: p.159","13C NMR, 60% depletion, labelled glucose: p.160, Figs 3–5","Coyle 1 h longer, same glycogen rate: p.161","Myoglobin: p.157","\"has not been found\": p.157","pH not significant: Fig 1 legend p.158","Funding: not stated."]}$ke$::jsonb, now());
INSERT INTO knowledge_entries (slug, status, entry, published_at) VALUES
  ('storey-smith-2012', 'published', $ke${"id": "storey-smith-2012","slug": "storey-smith-2012","source_pdf": "Unique_Aspects_of_Competitive_Weightlifitng.pdf","shape": "review","document_type": "journal article","meta_analysis": false,"key_findings": ["The second pull of a clean produces ~7,000 W of peak power — roughly 17× a bench press (415 W).","In junior lifters, moderate volume beat low and high: clean & jerk +10.5% vs +3.0%, squat +9.5% vs 5.3–6.9%, over 10 weeks.","Women lift 79–84% of men's world-record totals across age groups.","Masters lifters (40–87) keep ~32% more knee-extensor force and power than untrained peers, declining ~1–1.5% per year.","Lifters build some of the densest skeletons in sport: vertebrae +13–42% vs untrained — an advantage that persists into the 50s and 60s."],"header": {"title_plain": "Olympic weightlifters train harder and more often than any guideline allows — and the evidence says it works for them, within limits","citation": {"title": "Unique Aspects of Competitive Weightlifting","authors": "Storey A, Smith HK","year": "2012","journal": "Sports Med","volume_issue_pages": "42(9): 769–790","doi": "10.1007/BF03262294"},"topics": ["weightlifting","snatch","clean-and-jerk","power","training-frequency","periodization","nutrition","weight-cutting","masters","women","bone","hormones"],"evidence_type": "Narrative review of English-language research 1970s–Feb 2012 (PubMed, SPORTDiscus, Google Scholar). No new data; no funding; no conflicts.","confidence": {"level": "conceptual","why": "Conceptual, but numerically dense — most figures come from small studies of elite men."},"practical_relevance": {"level": "medium","why": "Ceiling data from elite men; peak-power load (70–80% 1RM) and the junior volume finding are the actionable points."},"author_stance": "none apparent","funding_and_conflicts": "No funding; no conflicts."},"layer1": {"review": {"claim": "Competitive weightlifting produces the highest power outputs and fastest force development recorded in sport, through training that is more frequent and more intense than conventional recommendations. The adaptations (muscle, bone, heart, hormones) look physiological rather than harmful. Nearly all evidence is from young elite men; women, under-17s and over-35s are under-researched.","definitions_used": [],"evidence_cited": [{"finding": "The lifts: Snatch: 6 phases, 3–5 s effort; C&J: 12 phases, 8–12 s. C&J load ~18–20% greater than snatch","source": "as reviewed","numbers": "Bar speed at max: snatch 1.65–2.28 m/s, clean 0.88–1.73 m/s; submax lifts >3.0 / >2.5 m/s. Jerk drive power 2,140 W (56 kg class) to 4,786 W (105+ kg). Transition into jerk can load ~17× body mass","note": ""},{"finding": "Power vs other athletes: Second pull produces the highest power in the literature","source": "as reviewed","numbers": "Absolute 5,442 W (snatch), 6,981 W (C&J); relative 53–56 W/kg men, 38–40 W/kg women. Compare bench press 415 W, deadlift 1,274 W, ~4–12 W/kg","note": ""},{"finding": "Strength and rate of force: Lifters beat other strength/power athletes on both","source": "as reviewed","numbers": "Isometric peak force ~15–20% higher; rate of force development ~13–16% higher. Lifts reach peak force in <260 ms vs 300–400 ms isometrically. Lower-body power 13–36% higher than other power athletes; upper-body power no different from handball players","note": ""},{"finding": "Soviet model: Classic periodization, wide variety","source": "as reviewed","numbers": "20,000–25,000 multi-joint reps/yr; 15–35% of them competition lifts at 80–90% 1RM; 4–7% at ≥90%","note": ""},{"finding": "Bulgarian model: Near-max loading, little intensity variation, volume waves","source": "as reviewed","numbers": "1,400–4,000 max attempts/yr plus ~450–460 failed supramax; time split 10% warm-up / 45% competition lifts / 40% complementary strength / 3% supplementary / 2% other; 2–3 weeks loading then 1 week reduced","note": ""},{"finding": "Frequency: Far above ACSM's 4–6 sessions/week for advanced trainees","source": "as reviewed","numbers": "≥2 sessions/day at ≥80% 1RM, 6–7 days/week, same muscle groups. Greek 1996 Olympic prep: 13 snatch, 11 C&J, 11 back-squat, 9 front-squat sessions in one 6-day week. Splitting a day's volume into two sessions gave greater strength and hypertrophy in seniors","note": ""},{"finding": "Volume by age: Proposed inverted-U: juniors and masters tolerate less","source": "as reviewed","numbers": "Juniors (17–20 y), 10 weeks, >90–100% 1RM: moderate volume +10.5% C&J, +9.5% back squat; low volume +3.0% / +5.3%; high volume +6.9% squat only. Extra same-day sessions didn't help juniors. Masters (≥35) show declining tolerance","note": ""},{"finding": "Load for power: Peak power load depends on the exercise","source": "as reviewed","numbers": "Ballistic (jump squat, bench throw): 30–50% 1RM, possibly as low as body weight. Snatch/C&J: 70–80% 1RM, so lifters train the competition lifts at ≥70%","note": ""},{"finding": "Energy and diet: High expenditure; protein and fat over-consumed, carbohydrate under","source": "as reviewed","numbers": "Training ~39.5 kJ/min; ~16,456 kJ/week from training alone. Intake 13,212–19,307 kJ/day (recommended 14,700–23,100). Protein 1.6–3.2 g/kg/day vs recommended 1.2–1.7; fat 40–44% of energy vs 20–35% acceptable; carbohydrate 2.9–6.1 g/kg/day vs 7–8 recommended","note": ""},{"finding": "Weight cutting: Mild dehydration is recoverable; severe isn't","source": "as reviewed","numbers": "Lifters train 5–10% above class. ≤2% body-mass loss from dehydration: performance restored with ~2 h rehydration. 3–4%: impairment not recoverable in time. Recommendation: diet to ≤2% above class, then mild dehydration only in the last 24 h","note": ""},{"finding": "Body composition: Light/middle classes lean; heavy classes not","source": "as reviewed","numbers": "5–10% fat (≤56–85 kg men), ≥17% (≥94 kg). Women possibly ~double men's fat %. Elite lifters leaner than lower-level lifters of the same weight. Shorter limbs and height = less torque, shorter bar path, larger muscle cross-section","note": ""},{"finding": "Muscle fibres: Same fast-twitch % as untrained, but bigger type II fibres","source": "as reviewed","numbers": "53–65% fast-twitch in vastus lateralis. Performance correlates with type IIA % (r = 0.94) and IIA area (r = 0.83). IIX→IIA shift with training","note": ""},{"finding": "Sex differences: Weightlifting training shrinks the gap","source": "as reviewed","numbers": "Untrained: men 31–48% stronger, 17–46% more powerful. Under-69 kg world records: women lift 79–84% of men's totals (youth 83.7%, junior 80.0%, senior 79.2%)","note": ""},{"finding": "Ageing: Masters lifters stay far ahead of untrained peers; decline ~1–1.5%/yr","source": "as reviewed","numbers": "Masters (40–87 y): 32% more knee-extensor force and power than untrained age-matched adults, with similar leg muscle volume (neural); motor-unit firing ~20% higher. Women decline faster (R² = 0.90 vs age) — not seen in powerlifting","note": ""},{"finding": "Bone: Densest skeletons in sport; benefit fades after ~65","source": "as reviewed","numbers": "Bone-formation markers up to 35% higher. Density: vertebrae +13–42%, femoral neck +12–24%, tibia +9–12%, radius +10% vs untrained/recreational. Retired lifters 50–64 y still higher than controls; 65–79 y no difference","note": ""},{"finding": "Heart: Bigger left ventricle, but proportional to body size = physiological","source": "as reviewed","numbers": "LV mass ~13–30% larger in some studies, not in others; scales with body mass. VO2max 42.0–50.7 ml/kg/min. 8 weeks of WL-style training in active adults: VO2max +6–7%; 3 years in competitive lifters: −4% absolute, −11% relative. Resting HR 60–81, BP 115–153/71–93 (\"normal\" to stage-1 hypertensive)","note": ""},{"finding": "Hormones: Responses like conventional heavy training; T:C tracks volume","source": "as reviewed","numbers": "Basal testosterone 14.4–27.7 nmol/L (normal 12.1–34.7). Acute rise 17–30% after a hard session; bigger with >2 years' experience; no rise in competition. Elite women: 37% volume cut → basal T:C +72.5% over 5 weeks; male lifter: 54% volume increase over 2 weeks → T:C −60%. Growth hormone 4.5–13-fold acute rises","note": ""}],"recommendations_made": ["Weight cutting: diet to ≤2% above class, then mild dehydration only in the last 24 h."],"untested_or_contested": "Which programme design is best (Soviet vs Bulgarian vs Western) — no direct comparisons. Everything about women, under-17s and over-35s. Whether a taper restores IIX fibres in lifters. Optimal macronutrient balance. Whether high-load vs low-load weightlifting-derivative training is better for power athletes."}},"layer2": {"what_it_means": "The headline for a coach is that weightlifters are the most powerful athletes measured, and they got there by training the competitive lifts and their derivatives heavy and often. Peak power in the snatch and clean comes at 70–80% of max, not the 30–50% that works for jumps and throws — so if you program cleans for power, the bar needs to be heavy. The review's volume-by-age idea is useful: juniors responded best to moderate amounts of near-max lifting, not more, and masters tolerate less again. The bone data are striking (vertebrae up to 42% denser) and the heart data reassuring. The diet finding is the one most coaches will recognise: lifters eat plenty of protein and fat and not enough carbohydrate.","what_it_doesnt_mean": "This is a review, and much of it describes what elite lifters do rather than what has been tested. Training 6–7 days a week with two heavy sessions a day is reported in internationals who were selected for tolerating it; the review itself notes that the same frequency causes overtraining markers in other studies. The junior volume study is one trial of 10 weeks. Almost nothing here is about women, teenagers, masters, or beginners — the people most likely to walk into a gym. Heavy, frequent training by elite lifters tells you the ceiling, not the dose for a member.","questions_raised": []},"translation": ["Peak-power load for the snatch and clean and jerk: 70–80% of 1RM. For jumps and throws: 30–50% or lighter.","Elite practice: 2 sessions/day, 6–7 days/week, mostly at ≥80% 1RM — a ceiling, not a prescription.","Junior lifters: moderate amounts of heavy (>90%) lifting beat both less and more, over 10 weeks.","Making weight: lose no more than 2% body mass by dehydration, and only in the last 24 h; recover with 2 h of rehydration."],"glossary_candidates": [{"term": "1RM","definition": "The heaviest load you can lift once with good form; training loads are set as a percentage of it.","confidence_term_is_new": "likely"},{"term": "Rate of force development","definition": "How fast force rises after a contraction starts; the key quality in explosive lifts, where peak force arrives in a quarter of a second.","confidence_term_is_new": "likely"},{"term": "Periodization","definition": "Planning training in phases (preparation, competition, transition) that vary volume and intensity.","confidence_term_is_new": "likely"},{"term": "Hypertrophy","definition": "Growth in muscle fibre size.","confidence_term_is_new": "likely"},{"term": "Type IIA / IIX fibres","definition": "Two kinds of fast-twitch fibre; IIX are fastest but fatigue quickest, and training tends to convert IIX to IIA.","confidence_term_is_new": "likely"},{"term": "Left ventricular hypertrophy","definition": "Thickening of the heart's main pumping chamber; a problem in disease, but proportional growth with body size in athletes is normal.","confidence_term_is_new": "likely"},{"term": "Testosterone:cortisol ratio","definition": "A blood marker that tends to fall when training volume rises; used to monitor training stress.","confidence_term_is_new": "likely"},{"term": "Sinclair score","definition": "A formula that adjusts a weightlifting total for body weight so lifters in different classes can be compared.","confidence_term_is_new": "likely"},{"term": "Hypohydration","definition": "Being short of body water, usually deliberately before a weigh-in.","confidence_term_is_new": "likely"}],"charts": [{"template": "values_by_condition","title": "Peak power: weightlifting vs other lifts","series": [{"label": "Peak power (male)","values": [{"condition": "C&J second pull","value": 6981},{"condition": "Snatch","value": 5442},{"condition": "Deadlift","value": 1274},{"condition": "Bench press","value": 415}]}],"units": "W","approximate": true,"note": "All male; approximate, from cited studies."},{"template": "values_by_condition","title": "Bone density advantage vs untrained","series": [{"label": "Bone density advantage","values": [{"condition": "Vertebrae","value": "13–42"},{"condition": "Femoral neck","value": "12–24"},{"condition": "Tibia","value": "9–12"},{"condition": "Radius","value": "10"}]}],"units": "% higher than untrained/recreational","approximate": false,"note": "Show as ranges (values are range strings as printed)."},{"template": "grouped_change_bars","title": "Junior lifters: 10 weeks at low, moderate and high volume","series": [{"group": "C&J","values": [{"label": "Low volume","value": 3.0},{"label": "Moderate volume","value": 10.5},{"label": "High volume","value": null}]},{"group": "Back squat","values": [{"label": "Low volume","value": 5.3},{"label": "Moderate volume","value": 9.5},{"label": "High volume","value": 6.9}]}],"units": "% change","approximate": false,"note": "High-volume C&J change not reported (null)."},{"template": "values_by_condition","title": "Lifters' diet vs recommendation","series": [{"label": "Protein (g/kg)","values": [{"condition": "Lifters' intake","value": "1.6–3.2"},{"condition": "Recommended","value": "1.2–1.7"}]},{"label": "Fat (% of energy)","values": [{"condition": "Lifters' intake","value": "40–44"},{"condition": "Recommended","value": "20–35"}]},{"label": "Carbohydrate (g/kg)","values": [{"condition": "Lifters' intake","value": "2.9–6.1"},{"condition": "Recommended","value": "7–8"}]}],"units": "mixed: g/kg/day (protein, carbohydrate); % of energy (fat)","approximate": false,"note": "Values are range strings as printed."}],"verification_notes": ["All numbers are the review authors' reporting of cited studies; not verified against originals.","Lift phases, speeds, durations: pp.771–772","Jerk power 2,140–4,786 W, 17× body mass: p.772","Soviet/Bulgarian figures: p.774","Frequency, Greek team, ACSM: p.775","Junior volume study, inverted-U: p.775, Fig 3 p.776","Power loads 30–50% / 70–80%: pp.775–776","Energy and diet: p.776","Weight cutting: p.777","Body composition, anthropometry: p.777","Fibre %, r values: p.778","PF/RFD %, power W and W/kg: pp.778–779","Sex difference %, Table I: p.779","Masters 32%, 20%, decline, Fig 4: pp.779–780","Bone: p.780","Heart, VO2max, BP: pp.780–781","Hormones: pp.781–782","Funding/conflicts: p.783","Review scope: p.771"]}$ke$::jsonb, now());
INSERT INTO knowledge_entries (slug, status, entry, published_at) VALUES
  ('travis-2020', 'published', $ke${"id": "travis-2020","slug": "travis-2020","source_pdf": "Emphasizing_Task-Specific_Hypertrophy_to_Enhance_Sequential_Strength_and_Power_Performance.pdf","shape": "review","document_type": "position stand","meta_analysis": false,"key_findings": ["Not all muscle growth is equal: heavy loads grow fast-twitch (type II) fibres; light loads grow relatively more slow-twitch.","Strength athletes carry ~20% larger type II fibres than bodybuilders, whose growth is more even — same size, different machinery.","Muscle size tracks the big lifts (r = 0.63–0.91 with squat, bench and deadlift in national powerlifters).","High-volume growth can be partly non-contractile: six weeks of it grew muscle with a lower concentration of force-producing protein.","Training to failure wasn't better — the non-failure group showed greater type II growth and performance.","Their prescription for strength-power athletes — ~80–95% 1RM at low reps — is a theoretical threshold, not a tested comparison."],"header": {"title_plain": "Not all muscle growth is equal: for strength and power, grow the fast fibres with heavy loads, not everything with high reps","citation": {"title": "Emphasizing Task-Specific Hypertrophy to Enhance Sequential Strength and Power Performance","authors": "Travis SK, Ishida A, Taber CB, Fry AC, Stone MH","year": "2020","journal": "J Funct Morphol Kinesiol","volume_issue_pages": "5: 76","doi": "10.3390/jfmk5040076"},"topics": ["hypertrophy","strength","power","fibre-type","load","periodization","powerlifting","weightlifting","training-to-failure","squat-depth"],"evidence_type": "Narrative review / position paper from a strength-and-conditioning research group. Much of the mechanistic content is theoretical.","confidence": {"level": "conceptual","why": "A coherent argument with real supporting data, but one school of thought; the authors acknowledge disagreement in the field."},"practical_relevance": {"level": "high","why": "Bears on how to program hypertrophy phases for athletes."},"author_stance": "one strength-and-conditioning research group with a stated position; explicitly disagrees with Loenneke's group on size vs strength","funding_and_conflicts": "No funding; no conflicts."},"layer1": {"review": {"claim": "\"Hypertrophy\" is not one thing. Bodybuilders and strength athletes can have similar muscle size but very different strength, because which fibres grew and what grew inside them differ. For strength and power, the goal should be optimal rather than maximal hypertrophy: grow type II fibres preferentially (raise the type II : type I size ratio), grow contractile protein rather than non-contractile cell volume, grow the regions of muscles that the competition lift uses, and sequence hypertrophy → strength → power so each phase sets up the next.","definitions_used": [],"evidence_cited": [{"finding": "Growth signalling tracks strength gains","source": "Terzis 2008, 14 weeks","numbers": "p70S6K activation correlated with gains in fat-free mass (r = 0.81–0.89), squat 1RM (r = 0.84), type II fibre size (r = 0.82)","note": ""},{"finding": "Load determines which fibres grow","source": "Grgic & Schoenfeld 2018 meta-analysis","numbers": "high load → type II growth; low load → relatively more type I","note": ""},{"finding": "Strength athletes have bigger fast fibres than bodybuilders","source": "several","numbers": "~20% greater type II fibre area in powerlifters/weightlifters; type II fibres up to twice the size of type I vs bodybuilders' more even profile","note": ""},{"finding": "Light-load training grows slow fibres","source": "Bjørnsen 2019, Norwegian powerlifters, blood-flow restriction at ~30% 1RM","numbers": "type I +12%, type II +4%; front squat improved (authors attribute partly to novelty)","note": ""},{"finding": "Muscle size predicts lifting","source": "Brechue & Abe 2002","numbers": "r = 0.63–0.91 between muscle size and squat/bench/deadlift in national powerlifters","note": ""},{"finding": "Architecture has limits","source": "Abe 2018 case","numbers": "theoretical pennation-angle limit ~30°; a world-champion raw powerlifter measured 33° (477.5 kg squat)","note": "Single case."},{"finding": "High-volume growth may be non-contractile","source": "Haun 2019","numbers": "6 weeks of high-volume training: growth mostly sarcoplasmic, with lower actin/myosin concentration","note": ""},{"finding": "Training to failure isn't better","source": "Carroll 2018/2019","numbers": "non-failure group showed greater type II hypertrophy and performance than failure group","note": ""},{"finding": "Range of motion matters","source": "Kubo 2019; Bloomquist 2013","numbers": "full squats produced greater growth across more muscles than half squats over 10 weeks","note": ""},{"finding": "Thresholds (theoretical)","source": "—","numbers": "~60% 1RM for whole-muscle growth; ≥80% to target high-threshold motor units; ≥10 reps/set for ~6 weeks may raise AMPK signalling that interferes with type II growth","note": "Labelled theoretical by the authors."}],"recommendations_made": ["Hypertrophy phase for strength/power athletes: 80–95% 1RM, ~5 reps/set, not to failure.","Use full range of motion and competition-specific exercises.","Precede with 2–4 weeks of general hypertrophy/strength-endurance to prime the process.","Sequence phases (phase potentiation)."],"untested_or_contested": "Whether size and strength are \"completely separate\" (they argue no; Loenneke's group argues yes). Fibre-type shift findings are often misclassified. Sarcoplasmic hypertrophy remains controversial. The load thresholds are \"theoretical.\" They call for studies combining ultrasound, biopsy and 1RM testing."}},"layer2": {"what_it_means": "This is the case for lifting heavy even when the goal is size, if the size is meant to serve strength or power. The supporting facts are solid: heavy loads preferentially grow fast-twitch fibres, strength athletes carry bigger fast fibres than bodybuilders of similar overall size, going to failure doesn't improve fast-fibre growth, and full-depth squats grow more muscle than half squats. For a coach, the practical shape is a hypertrophy block built on 5-ish reps at 80–95% rather than 10–15 reps at 65%, with full range of motion and reps in reserve, followed by strength and power blocks that cash in the new tissue.","what_it_doesnt_mean": "It doesn't say high-rep training is useless — it's the better route to type I growth and general muscle mass, and the authors themselves recommend 2–4 weeks of it first. The molecular story (mTOR, AMPK, myostatin, miRNA) is largely reasoning from mechanism, not from training outcomes; the paper is explicit that the load thresholds are theoretical. It's written by one research group with a known position, and some of its evidence is elite-athlete observation and single-case data. For general-population members chasing size and health, most of this is beside the point.","questions_raised": []},"translation": ["Strength/power hypertrophy block: 80–95% 1RM, ~5 reps per set, stop short of failure, full depth, lifts that look like the sport.","Light, high-rep work grows slow-twitch fibres; heavy work grows fast-twitch.","Full squats beat half squats for muscle growth (10 weeks)."],"glossary_candidates": [{"term": "Myofibrillar vs sarcoplasmic hypertrophy","definition": "Growth of the force-producing filaments vs growth of the fluid and non-contractile contents of the fibre; both make muscle bigger, only the first makes it proportionally stronger.","confidence_term_is_new": "likely"},{"term": "Type II : type I size ratio","definition": "How much bigger fast fibres are than slow ones; higher in strength and power athletes.","confidence_term_is_new": "likely"},{"term": "Pennation angle","definition": "The angle fibres sit at relative to the line of pull; increases with hypertrophy and raises force at some cost to speed.","confidence_term_is_new": "likely"},{"term": "Sarcomeres in series / in parallel","definition": "More in parallel = more force; more in series = more speed and range.","confidence_term_is_new": "likely"},{"term": "mTOR / AMPK","definition": "Two opposing cell signals: mTOR drives growth; AMPK responds to endurance-type stress and can dampen it.","confidence_term_is_new": "likely"},{"term": "Phase potentiation","definition": "Ordering training blocks so each one sets up the next (e.g. hypertrophy → strength → power).","confidence_term_is_new": "likely"},{"term": "Training to failure","definition": "Continuing a set until no more reps are possible.","confidence_term_is_new": "likely"},{"term": "Regional hypertrophy","definition": "Growth concentrated in one part of a muscle, depending on the exercise and range of motion.","confidence_term_is_new": "likely"}],"charts": [{"template": "concept_curve","title": "Load → which fibres grow","series": [{"label": "Type I emphasis","points": [{"x": 30,"y": 1},{"x": 60,"y": 0.5},{"x": 80,"y": 0}]},{"label": "Type II emphasis","points": [{"x": 30,"y": 0},{"x": 60,"y": 0.5},{"x": 80,"y": 1}]}],"units": "x = load, % 1RM (thresholds as printed); y = 1 if the authors say this fibre type is emphasised at that load, 0 if not — a category, not a measurement","approximate": true,"note": "schematic — not measured data. <60% 1RM → type I; 60–80% → mixed; ≥80% → type II. Thresholds are labelled theoretical by the authors; y values are illustrative only."},{"template": "grouped_change_bars","title": "Bjørnsen 2019: fibre growth with light-load BFR training","series": [{"group": "Blood-flow restriction at ~30% 1RM","values": [{"label": "Type I","value": 12},{"label": "Type II","value": 4}]}],"units": "% change in fibre size","approximate": false,"note": "Norwegian powerlifters. Review authors' reporting of Bjørnsen 2019. Other chart data in the hand entry not charted separately: Terzis correlations 0.81–0.89 / 0.84 / 0.82 (in evidence_cited)."}],"verification_notes": ["All numbers are the review authors' reporting of cited studies; not verified against originals.","Three stimuli, mechanisms: pp.2–5","Terzis r values: p.4","≥10 reps/6 weeks AMPK: p.4","Grgic & Schoenfeld: p.4","Pennation 30°/33°, 477.5 kg: p.5","Brechue & Abe r: p.6","20% type II, twice the size: p.7","60% / 80% thresholds, \"theoretical\": p.7","Bjørnsen 12%/4%: p.8","Haun sarcoplasmic: p.9","Carroll failure vs non-failure: p.10","Kubo full vs half: p.11","2–4 weeks priming: p.12","80–95%, 5 reps: p.13","Disagreement with Loenneke: pp.2, 14","Funding/conflicts: p.14."]}$ke$::jsonb, now());
