-- Research library corpus moves from static JSON in the app bundle to the
-- database, so an approved entry publishes instantly with no deploy.
-- The ingestion pipeline (edge function + admin review) writes via service
-- role; the public reads published rows only. The twelve founding entries
-- are seeded below, verbatim from src/data/knowledge/entries at this commit.

CREATE TABLE knowledge_entries (
  slug text PRIMARY KEY,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'rejected')),
  entry jsonb NOT NULL,
  validator_report jsonb,
  source_pdf_path text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz
);

ALTER TABLE knowledge_entries ENABLE ROW LEVEL SECURITY;

-- The library is free to read by construction; drafts stay invisible.
CREATE POLICY ke_select_published ON knowledge_entries FOR SELECT USING (status = 'published');
-- No insert/update/delete policies: writes go through the ingestion edge
-- function and admin review using the service role.

COMMENT ON TABLE knowledge_entries IS
  'Research library corpus. entry holds the full knowledge-entry JSON (see src/data/knowledge/ingestion-prompt.md for the contract); published rows render at /knowledge/<slug>.';

